window.JCSQE_QUESTIONS = [{"id":"E01Q01","exam":1,"number":1,"category":"品質概念","question":"Verificationの説明として最も適切なものはどれか。","options":{"A":"利用者のニーズに合う製品かを確認する","B":"成果物が規定要求どおり正しく作られているか確認する","C":"運用コストだけを確認する","D":"市場シェアを確認する"},"answer":"B","explanation":"Verificationは「正しく作っているか」を確認する。Validationは「正しいものを作っているか」。"},{"id":"E01Q02","exam":1,"number":2,"category":"品質概念","question":"Validationの説明として最も適切なものはどれか。","options":{"A":"利用者の意図した用途・ニーズを満たすか確認する","B":"構成品目を識別する","C":"欠陥密度を測る","D":"成果物が上位仕様に適合しているかだけを見る"},"answer":"A","explanation":"Validationは意図した用途や利用者ニーズを満たすかを確認する。"},{"id":"E01Q03","exam":1,"number":3,"category":"品質モデル","question":"通常運用時に信頼性要求を満たして安定して動作する性質はどれか。","options":{"A":"障害許容性","B":"回復性","C":"成熟性","D":"可用性"},"answer":"C","explanation":"平常時＝成熟性。"},{"id":"E01Q04","exam":1,"number":4,"category":"品質モデル","question":"障害発生中でも必要な機能を継続できる性質はどれか。","options":{"A":"回復性","B":"成熟性","C":"可用性","D":"障害許容性"},"answer":"D","explanation":"障害中＝障害許容性。"},{"id":"E01Q05","exam":1,"number":5,"category":"品質モデル","question":"障害後にデータや状態を復旧できる性質はどれか。","options":{"A":"成熟性","B":"可用性","C":"障害許容性","D":"回復性"},"answer":"D","explanation":"障害後＝回復性。"},{"id":"E01Q06","exam":1,"number":6,"category":"品質モデル","question":"必要な時にシステムを利用できる性質はどれか。","options":{"A":"可用性","B":"障害許容性","C":"回復性","D":"成熟性"},"answer":"A","explanation":"利用可能である度合い＝可用性。"},{"id":"E01Q07","exam":1,"number":7,"category":"保守性","question":"あるモジュールの変更が他モジュールへ波及しにくい性質はどれか。","options":{"A":"修正性","B":"試験性","C":"解析性","D":"モジュール性"},"answer":"D","explanation":"変更影響の局所化＝モジュール性。"},{"id":"E01Q08","exam":1,"number":8,"category":"保守性","question":"障害原因や変更対象を調査しやすい性質はどれか。","options":{"A":"試験性","B":"解析性","C":"再利用性","D":"修正性"},"answer":"B","explanation":"原因・変更箇所を分析しやすい＝解析性。"},{"id":"E01Q09","exam":1,"number":9,"category":"保守性","question":"変更後のソフトウェアを効率よくテストできる性質はどれか。","options":{"A":"解析性","B":"再利用性","C":"修正性","D":"試験性"},"answer":"D","explanation":"テストしやすさ＝試験性。"},{"id":"E01Q10","exam":1,"number":10,"category":"セキュリティ","question":"許可されていない者による情報閲覧を防ぐ性質はどれか。","options":{"A":"インテグリティ","B":"真正性","C":"責任追跡性","D":"機密性"},"answer":"D","explanation":"見せない＝機密性。"},{"id":"E01Q11","exam":1,"number":11,"category":"セキュリティ","question":"権限のない変更・改ざんを防ぐ性質はどれか。","options":{"A":"真正性","B":"否認防止性","C":"機密性","D":"インテグリティ"},"answer":"D","explanation":"変えさせない＝インテグリティ。"},{"id":"E01Q12","exam":1,"number":12,"category":"セキュリティ","question":"操作を行った主体を後から追跡できる性質はどれか。","options":{"A":"機密性","B":"真正性","C":"責任追跡性","D":"否認防止性"},"answer":"C","explanation":"誰が行ったか追える＝責任追跡性。"},{"id":"E01Q13","exam":1,"number":13,"category":"セキュリティ","question":"利用者が主張どおりの本人であることを確認する性質はどれか。","options":{"A":"真正性","B":"責任追跡性","C":"否認防止性","D":"インテグリティ"},"answer":"A","explanation":"本当に本人か＝真正性。"},{"id":"E01Q14","exam":1,"number":14,"category":"セキュリティ","question":"電子的な操作を後から『自分はしていない』と否定できないようにする性質はどれか。","options":{"A":"責任追跡性","B":"否認防止性","C":"機密性","D":"真正性"},"answer":"B","explanation":"行為の否定を防ぐ＝否認防止性。"},{"id":"E01Q15","exam":1,"number":15,"category":"レビュー","question":"インスペクションの特徴として最も適切なものはどれか。","options":{"A":"必ずプログラムを実行する","B":"テスト完了後だけ行う","C":"作成者だけで自由に確認する","D":"役割や手順を定め体系的に行う"},"answer":"D","explanation":"インスペクションは比較的形式的なレビュー。"},{"id":"E01Q16","exam":1,"number":16,"category":"レビュー","question":"ウォークスルーの特徴として最も適切なものはどれか。","options":{"A":"構成管理の一種である","B":"作成者が説明を主導することが多い","C":"必ず監査部門が主導する","D":"動的テストの一種である"},"answer":"B","explanation":"ウォークスルーは作成者主導で説明・確認する形が代表的。"},{"id":"E01Q17","exam":1,"number":17,"category":"テスト","question":"同値分割法の説明として最も適切なものはどれか。","options":{"A":"同様の振る舞いが期待される入力集合に分割する","B":"境界値だけを試す","C":"内部分岐をすべて実行する","D":"無作為値だけを使う"},"answer":"A","explanation":"同値クラスごとに代表値を選ぶ。"},{"id":"E01Q18","exam":1,"number":18,"category":"テスト","question":"入力範囲が1以上100以下のとき、境界値分析で特に有効な組合せはどれか。","options":{"A":"1,100","B":"0,1,100,101","C":"10,20,30,40","D":"25,50,75"},"answer":"B","explanation":"境界の直前・境界・直後を重視する。"},{"id":"E01Q19","exam":1,"number":19,"category":"テスト","question":"複数条件の組合せと結果の関係を整理してテストする技法はどれか。","options":{"A":"命令網羅","B":"探索的テスト","C":"状態遷移テスト","D":"デシジョンテーブルテスト"},"answer":"D","explanation":"条件組合せ＝デシジョンテーブル。"},{"id":"E01Q20","exam":1,"number":20,"category":"テスト","question":"状態によって同じイベントへの応答が変化するシステムに適した技法はどれか。","options":{"A":"静的解析","B":"状態遷移テスト","C":"同値分割","D":"分岐網羅"},"answer":"B","explanation":"状態と遷移を持つ対象には状態遷移テスト。"},{"id":"E01Q21","exam":1,"number":21,"category":"テスト","question":"変更による既存機能への悪影響を確認するテストはどれか。","options":{"A":"受入テスト","B":"回帰テスト","C":"負荷テスト","D":"ユーザビリティテスト"},"answer":"B","explanation":"変更後の副作用確認＝回帰テスト。"},{"id":"E01Q22","exam":1,"number":22,"category":"テスト","question":"内部の制御構造を基に網羅率を測るテストはどれか。","options":{"A":"ホワイトボックステスト","B":"受入テスト","C":"ユーザビリティテスト","D":"ブラックボックステスト"},"answer":"A","explanation":"命令・分岐など内部構造に着目＝ホワイトボックス。"},{"id":"E01Q23","exam":1,"number":23,"category":"テスト","question":"テストで欠陥が見つからなかった場合の判断として適切なのはどれか。","options":{"A":"実施したテストでは発見されなかっただけである","B":"テストは不要だった","C":"欠陥が存在しないことが証明された","D":"品質100%である"},"answer":"A","explanation":"テストは欠陥の不在を完全には証明できない。"},{"id":"E01Q24","exam":1,"number":24,"category":"品質管理","question":"パレート図の主な用途はどれか。","options":{"A":"原因候補を枝状に整理する","B":"時系列変化を監視する","C":"重要な問題を優先順位付けする","D":"二変数の相関を見る"},"answer":"C","explanation":"大きい項目から並べ重点問題を把握する。"},{"id":"E01Q25","exam":1,"number":25,"category":"品質管理","question":"特性要因図の主な用途はどれか。","options":{"A":"原因候補を体系的に整理する","B":"頻度順に並べる","C":"時系列の管理限界を見る","D":"テストケースを生成する"},"answer":"A","explanation":"結果と原因候補を魚の骨状に整理する。"},{"id":"E01Q26","exam":1,"number":26,"category":"品質管理","question":"散布図の主な用途はどれか。","options":{"A":"原因候補を階層化する","B":"頻度順に並べる","C":"構成品目を管理する","D":"二つの変数の関係を観察する"},"answer":"D","explanation":"二変数間の関係を見る。"},{"id":"E01Q27","exam":1,"number":27,"category":"品質管理","question":"管理図の主な用途はどれか。","options":{"A":"コードを自動生成する","B":"レビュー役割を定義する","C":"プロセスの変動が統計的に安定しているか監視する","D":"機能要求を整理する"},"answer":"C","explanation":"管理限界などを用いて工程の安定性を見る。"},{"id":"E01Q28","exam":1,"number":28,"category":"品質コスト","question":"品質教育や標準化活動に要する費用はどれか。","options":{"A":"外部失敗コスト","B":"予防コスト","C":"評価コスト","D":"内部失敗コスト"},"answer":"B","explanation":"不良を未然に防ぐ活動＝予防コスト。"},{"id":"E01Q29","exam":1,"number":29,"category":"品質コスト","question":"出荷前の検査・テストに要する費用はどれか。","options":{"A":"予防コスト","B":"評価コスト","C":"内部失敗コスト","D":"外部失敗コスト"},"answer":"B","explanation":"適合性を評価する活動＝評価コスト。"},{"id":"E01Q30","exam":1,"number":30,"category":"品質コスト","question":"出荷前に発見された欠陥の修正費用はどれか。","options":{"A":"評価コスト","B":"内部失敗コスト","C":"外部失敗コスト","D":"予防コスト"},"answer":"B","explanation":"顧客へ渡る前の失敗＝内部失敗コスト。"},{"id":"E01Q31","exam":1,"number":31,"category":"品質コスト","question":"市場で発生した障害・クレームへの対応費用はどれか。","options":{"A":"内部失敗コスト","B":"外部失敗コスト","C":"予防コスト","D":"評価コスト"},"answer":"B","explanation":"顧客へ渡った後の失敗＝外部失敗コスト。"},{"id":"E01Q32","exam":1,"number":32,"category":"メトリクス","question":"GQMの正しい展開順序はどれか。","options":{"A":"Goal→Query→Model","B":"Goal→Quality→Metric","C":"Goal→Question→Metric","D":"Graph→Question→Measure"},"answer":"C","explanation":"GQM = Goal, Question, Metric。"},{"id":"E01Q33","exam":1,"number":33,"category":"メトリクス","question":"欠陥密度の例として最も適切なものはどれか。","options":{"A":"KLOC当たりの欠陥数","B":"1日当たり勤務時間","C":"CPU使用率","D":"平均給与"},"answer":"A","explanation":"規模当たり欠陥数が代表例。"},{"id":"E01Q34","exam":1,"number":34,"category":"信頼性指標","question":"MTBFが表すものはどれか。","options":{"A":"平均故障間隔","B":"平均応答時間","C":"平均テスト時間","D":"平均修復時間"},"answer":"A","explanation":"MTBF = Mean Time Between Failures。"},{"id":"E01Q35","exam":1,"number":35,"category":"信頼性指標","question":"MTTRが一般に表すものはどれか。","options":{"A":"平均レビュー時間","B":"平均要求数","C":"平均修復時間","D":"平均故障間隔"},"answer":"C","explanation":"MTTR = Mean Time To Repair/Recovery。"},{"id":"E01Q36","exam":1,"number":36,"category":"統計","question":"1つの目的変数を複数の説明変数から説明・予測する代表的手法はどれか。","options":{"A":"パレート分析","B":"重回帰分析","C":"クラスター分析","D":"因子分析"},"answer":"B","explanation":"複数説明変数→1目的変数＝重回帰分析。"},{"id":"E01Q37","exam":1,"number":37,"category":"統計","question":"似た特徴を持つ対象をグループ化する手法はどれか。","options":{"A":"重回帰分析","B":"クラスター分析","C":"因子分析","D":"管理図"},"answer":"B","explanation":"類似対象のグループ化＝クラスター分析。"},{"id":"E01Q38","exam":1,"number":38,"category":"統計","question":"観測変数の背後にある潜在的な因子を探る手法はどれか。","options":{"A":"クラスター分析","B":"因子分析","C":"散布図","D":"重回帰分析"},"answer":"B","explanation":"潜在因子の探索＝因子分析。"},{"id":"E01Q39","exam":1,"number":39,"category":"構成管理","question":"ベースラインの説明として適切なのはどれか。","options":{"A":"個人PCの一時保存","B":"バックアップだけを指す","C":"正式に合意され変更管理の対象となる基準状態","D":"最新ファイルなら何でもよい"},"answer":"C","explanation":"ベースライン変更は正式な変更管理下で行う。"},{"id":"E01Q40","exam":1,"number":40,"category":"構成管理","question":"構成管理で不適切な行為はどれか。","options":{"A":"リリース対象を管理する","B":"構成品目を識別する","C":"変更履歴を記録する","D":"担当者個人が無手続でベースライン変更を確定する"},"answer":"D","explanation":"ベースライン変更は権限ある仕組みで統制する。 ---"},{"id":"E02Q01","exam":2,"number":1,"category":"品質計画","question":"品質計画について最も適切なものはどれか。","options":{"A":"一度作れば固定する","B":"要求やプロセス変更に応じて見直す","C":"合否基準を含めない","D":"品質評価計画を含めない"},"answer":"B","explanation":"品質計画は状況変化に応じて更新する。"},{"id":"E02Q02","exam":2,"number":2,"category":"改善","question":"根本原因分析の目的として最も適切なものはどれか。","options":{"A":"根本原因を特定し再発防止につなげる","B":"障害を一時回避するだけ","C":"欠陥件数を減らして記録する","D":"責任者を処罰する"},"answer":"A","explanation":"原因の深掘りと再発防止が目的。"},{"id":"E02Q03","exam":2,"number":3,"category":"改善","question":"PDCAの正しい順序はどれか。","options":{"A":"Do→Plan→Act→Check","B":"Plan→Act→Do→Check","C":"Plan→Check→Do→Act","D":"Plan→Do→Check→Act"},"answer":"D","explanation":"Plan, Do, Check, Act。"},{"id":"E02Q04","exam":2,"number":4,"category":"リスク","question":"リスクベースドテストの考え方として適切なのはどれか。","options":{"A":"担当者の好みだけで決める","B":"全機能へ同量のテストを割り当てる","C":"発生可能性や影響度を考慮して優先度を決める","D":"テストを行わずリスク評価だけする"},"answer":"C","explanation":"高リスク領域へ重点的にテスト資源を配分する。"},{"id":"E02Q05","exam":2,"number":5,"category":"CI/CD","question":"CIの説明として最も適切なものはどれか。","options":{"A":"変更を頻繁に統合しビルドやテスト等を自動化する","B":"本番デプロイだけを指す","C":"統合を手作業中心にする","D":"自動化後は結果確認不要"},"answer":"A","explanation":"CIは継続的統合。自動化しても結果確認は必要。"},{"id":"E02Q06","exam":2,"number":6,"category":"ITサービス","question":"ITILが主に扱うものはどれか。","options":{"A":"ソースコード生成","B":"統計解析だけ","C":"UI設計だけ","D":"ITサービスマネジメント"},"answer":"D","explanation":"ITILはITサービスマネジメントのベストプラクティス。"},{"id":"E02Q07","exam":2,"number":7,"category":"セーフティ","question":"ハザードの説明として適切なのはどれか。","options":{"A":"品質目標","B":"構成品目","C":"危害を引き起こす潜在的な原因","D":"実際に生じた損害そのもの"},"answer":"C","explanation":"ハザード＝危害につながる潜在的原因。"},{"id":"E02Q08","exam":2,"number":8,"category":"セーフティ","question":"本質安全の考え方として最も近いものはどれか。","options":{"A":"ログを残すだけ","B":"ハザードそのものを除去・低減する","C":"ハザード発生後だけ警告する","D":"バックアップを取るだけ"},"answer":"B","explanation":"危険源そのものを抑える＝本質安全。"},{"id":"E02Q09","exam":2,"number":9,"category":"セーフティ","question":"機能安全の考え方として最も近いものはどれか。","options":{"A":"安全関連機能によって危害へ至るリスクを低減する","B":"危険源を物理的に必ずゼロにする","C":"可用性だけを高める","D":"暗号化だけを行う"},"answer":"A","explanation":"安全機能によってリスクを許容可能にする。"},{"id":"E02Q10","exam":2,"number":10,"category":"AI品質","question":"AIシステムの品質評価で適切なものはどれか。","options":{"A":"通常ソフトと完全に同じ観点だけで十分","B":"精度だけ見ればよい","C":"テストは不要","D":"学習データやモデル特性も含めて評価する"},"answer":"D","explanation":"データ・モデル特有の品質も考慮する。"},{"id":"E02Q11","exam":2,"number":11,"category":"IoT品質","question":"IoTシステムの品質で適切な考え方はどれか。","options":{"A":"ローカルPCだけを見る","B":"品質管理は不要","C":"デバイス・通信・クラウド等を含む全体を考慮する","D":"アプリ画面だけを見る"},"answer":"C","explanation":"複数要素からなるシステム全体で品質を捉える。"},{"id":"E02Q12","exam":2,"number":12,"category":"クラウド品質","question":"クラウド利用時の品質で考慮すべきものはどれか。","options":{"A":"性能は常に一定","B":"可用性・セキュリティ・サービス依存性など","C":"障害は起きないので品質活動不要","D":"テスト不要"},"answer":"B","explanation":"クラウド固有の依存関係や運用品質も考慮する。"},{"id":"E02Q13","exam":2,"number":13,"category":"品質概念","question":"ある業務システム開発で、verificationの説明として最も適切なものはどれか。","options":{"A":"成果物が規定要求どおり正しく作られているか確認する","B":"運用コストだけを確認する","C":"市場シェアを確認する","D":"利用者のニーズに合う製品かを確認する"},"answer":"A","explanation":"Verificationは「正しく作っているか」を確認する。Validationは「正しいものを作っているか」。"},{"id":"E02Q14","exam":2,"number":14,"category":"品質概念","question":"ある業務システム開発で、validationの説明として最も適切なものはどれか。","options":{"A":"構成品目を識別する","B":"欠陥密度を測る","C":"成果物が上位仕様に適合しているかだけを見る","D":"利用者の意図した用途・ニーズを満たすか確認する"},"answer":"D","explanation":"Validationは意図した用途や利用者ニーズを満たすかを確認する。"},{"id":"E02Q15","exam":2,"number":15,"category":"品質モデル","question":"ある業務システム開発で、通常運用時に信頼性要求を満たして安定して動作する性質はどれか。","options":{"A":"回復性","B":"成熟性","C":"可用性","D":"障害許容性"},"answer":"B","explanation":"平常時＝成熟性。"},{"id":"E02Q16","exam":2,"number":16,"category":"品質モデル","question":"ある業務システム開発で、障害発生中でも必要な機能を継続できる性質はどれか。","options":{"A":"成熟性","B":"可用性","C":"障害許容性","D":"回復性"},"answer":"C","explanation":"障害中＝障害許容性。"},{"id":"E02Q17","exam":2,"number":17,"category":"品質モデル","question":"ある業務システム開発で、障害後にデータや状態を復旧できる性質はどれか。","options":{"A":"可用性","B":"障害許容性","C":"回復性","D":"成熟性"},"answer":"C","explanation":"障害後＝回復性。"},{"id":"E02Q18","exam":2,"number":18,"category":"品質モデル","question":"ある業務システム開発で、必要な時にシステムを利用できる性質はどれか。","options":{"A":"障害許容性","B":"回復性","C":"成熟性","D":"可用性"},"answer":"D","explanation":"利用可能である度合い＝可用性。"},{"id":"E02Q19","exam":2,"number":19,"category":"保守性","question":"ある業務システム開発で、あるモジュールの変更が他モジュールへ波及しにくい性質はどれか。","options":{"A":"試験性","B":"解析性","C":"モジュール性","D":"修正性"},"answer":"C","explanation":"変更影響の局所化＝モジュール性。"},{"id":"E02Q20","exam":2,"number":20,"category":"保守性","question":"ある業務システム開発で、障害原因や変更対象を調査しやすい性質はどれか。","options":{"A":"解析性","B":"再利用性","C":"修正性","D":"試験性"},"answer":"A","explanation":"原因・変更箇所を分析しやすい＝解析性。"},{"id":"E02Q21","exam":2,"number":21,"category":"保守性","question":"ある業務システム開発で、変更後のソフトウェアを効率よくテストできる性質はどれか。","options":{"A":"再利用性","B":"修正性","C":"試験性","D":"解析性"},"answer":"C","explanation":"テストしやすさ＝試験性。"},{"id":"E02Q22","exam":2,"number":22,"category":"セキュリティ","question":"ある業務システム開発で、許可されていない者による情報閲覧を防ぐ性質はどれか。","options":{"A":"真正性","B":"責任追跡性","C":"機密性","D":"インテグリティ"},"answer":"C","explanation":"見せない＝機密性。"},{"id":"E02Q23","exam":2,"number":23,"category":"セキュリティ","question":"ある業務システム開発で、権限のない変更・改ざんを防ぐ性質はどれか。","options":{"A":"否認防止性","B":"機密性","C":"インテグリティ","D":"真正性"},"answer":"C","explanation":"変えさせない＝インテグリティ。"},{"id":"E02Q24","exam":2,"number":24,"category":"セキュリティ","question":"ある業務システム開発で、操作を行った主体を後から追跡できる性質はどれか。","options":{"A":"真正性","B":"責任追跡性","C":"否認防止性","D":"機密性"},"answer":"B","explanation":"誰が行ったか追える＝責任追跡性。"},{"id":"E02Q25","exam":2,"number":25,"category":"セキュリティ","question":"ある業務システム開発で、利用者が主張どおりの本人であることを確認する性質はどれか。","options":{"A":"責任追跡性","B":"否認防止性","C":"インテグリティ","D":"真正性"},"answer":"D","explanation":"本当に本人か＝真正性。"},{"id":"E02Q26","exam":2,"number":26,"category":"セキュリティ","question":"ある業務システム開発で、電子的な操作を後から『自分はしていない』と否定できないようにする性質はどれか。","options":{"A":"否認防止性","B":"機密性","C":"真正性","D":"責任追跡性"},"answer":"A","explanation":"行為の否定を防ぐ＝否認防止性。"},{"id":"E02Q27","exam":2,"number":27,"category":"レビュー","question":"ある業務システム開発で、インスペクションの特徴として最も適切なものはどれか。","options":{"A":"テスト完了後だけ行う","B":"作成者だけで自由に確認する","C":"役割や手順を定め体系的に行う","D":"必ずプログラムを実行する"},"answer":"C","explanation":"インスペクションは比較的形式的なレビュー。"},{"id":"E02Q28","exam":2,"number":28,"category":"レビュー","question":"ある業務システム開発で、ウォークスルーの特徴として最も適切なものはどれか。","options":{"A":"作成者が説明を主導することが多い","B":"必ず監査部門が主導する","C":"動的テストの一種である","D":"構成管理の一種である"},"answer":"A","explanation":"ウォークスルーは作成者主導で説明・確認する形が代表的。"},{"id":"E02Q29","exam":2,"number":29,"category":"テスト","question":"ある業務システム開発で、同値分割法の説明として最も適切なものはどれか。","options":{"A":"境界値だけを試す","B":"内部分岐をすべて実行する","C":"無作為値だけを使う","D":"同様の振る舞いが期待される入力集合に分割する"},"answer":"D","explanation":"同値クラスごとに代表値を選ぶ。"},{"id":"E02Q30","exam":2,"number":30,"category":"テスト","question":"入力範囲が1以上100以下のとき、境界値分析で特に有効な組合せはどれか。","options":{"A":"0,1,100,101","B":"10,20,30,40","C":"25,50,75","D":"1,100"},"answer":"A","explanation":"境界の直前・境界・直後を重視する。"},{"id":"E02Q31","exam":2,"number":31,"category":"テスト","question":"ある業務システム開発で、複数条件の組合せと結果の関係を整理してテストする技法はどれか。","options":{"A":"探索的テスト","B":"状態遷移テスト","C":"デシジョンテーブルテスト","D":"命令網羅"},"answer":"C","explanation":"条件組合せ＝デシジョンテーブル。"},{"id":"E02Q32","exam":2,"number":32,"category":"テスト","question":"ある業務システム開発で、状態によって同じイベントへの応答が変化するシステムに適した技法はどれか。","options":{"A":"状態遷移テスト","B":"同値分割","C":"分岐網羅","D":"静的解析"},"answer":"A","explanation":"状態と遷移を持つ対象には状態遷移テスト。"},{"id":"E02Q33","exam":2,"number":33,"category":"テスト","question":"ある業務システム開発で、変更による既存機能への悪影響を確認するテストはどれか。","options":{"A":"回帰テスト","B":"負荷テスト","C":"ユーザビリティテスト","D":"受入テスト"},"answer":"A","explanation":"変更後の副作用確認＝回帰テスト。"},{"id":"E02Q34","exam":2,"number":34,"category":"テスト","question":"ある業務システム開発で、内部の制御構造を基に網羅率を測るテストはどれか。","options":{"A":"受入テスト","B":"ユーザビリティテスト","C":"ブラックボックステスト","D":"ホワイトボックステスト"},"answer":"D","explanation":"命令・分岐など内部構造に着目＝ホワイトボックス。"},{"id":"E02Q35","exam":2,"number":35,"category":"テスト","question":"ある業務システム開発で、テストで欠陥が見つからなかった場合の判断として適切なのはどれか。","options":{"A":"テストは不要だった","B":"欠陥が存在しないことが証明された","C":"品質100%である","D":"実施したテストでは発見されなかっただけである"},"answer":"D","explanation":"テストは欠陥の不在を完全には証明できない。"},{"id":"E02Q36","exam":2,"number":36,"category":"品質管理","question":"ある業務システム開発で、パレート図の主な用途はどれか。","options":{"A":"時系列変化を監視する","B":"重要な問題を優先順位付けする","C":"二変数の相関を見る","D":"原因候補を枝状に整理する"},"answer":"B","explanation":"大きい項目から並べ重点問題を把握する。"},{"id":"E02Q37","exam":2,"number":37,"category":"品質管理","question":"ある業務システム開発で、特性要因図の主な用途はどれか。","options":{"A":"頻度順に並べる","B":"時系列の管理限界を見る","C":"テストケースを生成する","D":"原因候補を体系的に整理する"},"answer":"D","explanation":"結果と原因候補を魚の骨状に整理する。"},{"id":"E02Q38","exam":2,"number":38,"category":"品質管理","question":"ある業務システム開発で、散布図の主な用途はどれか。","options":{"A":"頻度順に並べる","B":"構成品目を管理する","C":"二つの変数の関係を観察する","D":"原因候補を階層化する"},"answer":"C","explanation":"二変数間の関係を見る。"},{"id":"E02Q39","exam":2,"number":39,"category":"品質管理","question":"ある業務システム開発で、管理図の主な用途はどれか。","options":{"A":"レビュー役割を定義する","B":"プロセスの変動が統計的に安定しているか監視する","C":"機能要求を整理する","D":"コードを自動生成する"},"answer":"B","explanation":"管理限界などを用いて工程の安定性を見る。"},{"id":"E02Q40","exam":2,"number":40,"category":"品質コスト","question":"ある業務システム開発で、品質教育や標準化活動に要する費用はどれか。","options":{"A":"予防コスト","B":"評価コスト","C":"内部失敗コスト","D":"外部失敗コスト"},"answer":"A","explanation":"不良を未然に防ぐ活動＝予防コスト。 ---"},{"id":"E03Q01","exam":3,"number":1,"category":"品質コスト","question":"ある業務システム開発で、出荷前の検査・テストに要する費用はどれか。","options":{"A":"評価コスト","B":"内部失敗コスト","C":"外部失敗コスト","D":"予防コスト"},"answer":"A","explanation":"適合性を評価する活動＝評価コスト。"},{"id":"E03Q02","exam":3,"number":2,"category":"品質コスト","question":"ある業務システム開発で、出荷前に発見された欠陥の修正費用はどれか。","options":{"A":"内部失敗コスト","B":"外部失敗コスト","C":"予防コスト","D":"評価コスト"},"answer":"A","explanation":"顧客へ渡る前の失敗＝内部失敗コスト。"},{"id":"E03Q03","exam":3,"number":3,"category":"品質コスト","question":"ある業務システム開発で、市場で発生した障害・クレームへの対応費用はどれか。","options":{"A":"外部失敗コスト","B":"予防コスト","C":"評価コスト","D":"内部失敗コスト"},"answer":"A","explanation":"顧客へ渡った後の失敗＝外部失敗コスト。"},{"id":"E03Q04","exam":3,"number":4,"category":"メトリクス","question":"ある業務システム開発で、gQMの正しい展開順序はどれか。","options":{"A":"Goal→Quality→Metric","B":"Goal→Question→Metric","C":"Graph→Question→Measure","D":"Goal→Query→Model"},"answer":"B","explanation":"GQM = Goal, Question, Metric。"},{"id":"E03Q05","exam":3,"number":5,"category":"メトリクス","question":"ある業務システム開発で、欠陥密度の例として最も適切なものはどれか。","options":{"A":"1日当たり勤務時間","B":"CPU使用率","C":"平均給与","D":"KLOC当たりの欠陥数"},"answer":"D","explanation":"規模当たり欠陥数が代表例。"},{"id":"E03Q06","exam":3,"number":6,"category":"信頼性指標","question":"ある業務システム開発で、mTBFが表すものはどれか。","options":{"A":"平均応答時間","B":"平均テスト時間","C":"平均修復時間","D":"平均故障間隔"},"answer":"D","explanation":"MTBF = Mean Time Between Failures。"},{"id":"E03Q07","exam":3,"number":7,"category":"信頼性指標","question":"ある業務システム開発で、mTTRが一般に表すものはどれか。","options":{"A":"平均要求数","B":"平均修復時間","C":"平均故障間隔","D":"平均レビュー時間"},"answer":"B","explanation":"MTTR = Mean Time To Repair/Recovery。"},{"id":"E03Q08","exam":3,"number":8,"category":"統計","question":"1つの目的変数を複数の説明変数から説明・予測する代表的手法はどれか。","options":{"A":"重回帰分析","B":"クラスター分析","C":"因子分析","D":"パレート分析"},"answer":"A","explanation":"複数説明変数→1目的変数＝重回帰分析。"},{"id":"E03Q09","exam":3,"number":9,"category":"統計","question":"ある業務システム開発で、似た特徴を持つ対象をグループ化する手法はどれか。","options":{"A":"クラスター分析","B":"因子分析","C":"管理図","D":"重回帰分析"},"answer":"A","explanation":"類似対象のグループ化＝クラスター分析。"},{"id":"E03Q10","exam":3,"number":10,"category":"統計","question":"ある業務システム開発で、観測変数の背後にある潜在的な因子を探る手法はどれか。","options":{"A":"因子分析","B":"散布図","C":"重回帰分析","D":"クラスター分析"},"answer":"A","explanation":"潜在因子の探索＝因子分析。"},{"id":"E03Q11","exam":3,"number":11,"category":"構成管理","question":"ある業務システム開発で、ベースラインの説明として適切なのはどれか。","options":{"A":"バックアップだけを指す","B":"正式に合意され変更管理の対象となる基準状態","C":"最新ファイルなら何でもよい","D":"個人PCの一時保存"},"answer":"B","explanation":"ベースライン変更は正式な変更管理下で行う。"},{"id":"E03Q12","exam":3,"number":12,"category":"構成管理","question":"ある業務システム開発で、構成管理で不適切な行為はどれか。","options":{"A":"構成品目を識別する","B":"変更履歴を記録する","C":"担当者個人が無手続でベースライン変更を確定する","D":"リリース対象を管理する"},"answer":"C","explanation":"ベースライン変更は権限ある仕組みで統制する。"},{"id":"E03Q13","exam":3,"number":13,"category":"品質計画","question":"ある業務システム開発で、品質計画について最も適切なものはどれか。","options":{"A":"要求やプロセス変更に応じて見直す","B":"合否基準を含めない","C":"品質評価計画を含めない","D":"一度作れば固定する"},"answer":"A","explanation":"品質計画は状況変化に応じて更新する。"},{"id":"E03Q14","exam":3,"number":14,"category":"改善","question":"ある業務システム開発で、根本原因分析の目的として最も適切なものはどれか。","options":{"A":"障害を一時回避するだけ","B":"欠陥件数を減らして記録する","C":"責任者を処罰する","D":"根本原因を特定し再発防止につなげる"},"answer":"D","explanation":"原因の深掘りと再発防止が目的。"},{"id":"E03Q15","exam":3,"number":15,"category":"改善","question":"ある業務システム開発で、pDCAの正しい順序はどれか。","options":{"A":"Plan→Act→Do→Check","B":"Plan→Check→Do→Act","C":"Plan→Do→Check→Act","D":"Do→Plan→Act→Check"},"answer":"C","explanation":"Plan, Do, Check, Act。"},{"id":"E03Q16","exam":3,"number":16,"category":"リスク","question":"ある業務システム開発で、リスクベースドテストの考え方として適切なのはどれか。","options":{"A":"全機能へ同量のテストを割り当てる","B":"発生可能性や影響度を考慮して優先度を決める","C":"テストを行わずリスク評価だけする","D":"担当者の好みだけで決める"},"answer":"B","explanation":"高リスク領域へ重点的にテスト資源を配分する。"},{"id":"E03Q17","exam":3,"number":17,"category":"CI/CD","question":"ある業務システム開発で、cIの説明として最も適切なものはどれか。","options":{"A":"本番デプロイだけを指す","B":"統合を手作業中心にする","C":"自動化後は結果確認不要","D":"変更を頻繁に統合しビルドやテスト等を自動化する"},"answer":"D","explanation":"CIは継続的統合。自動化しても結果確認は必要。"},{"id":"E03Q18","exam":3,"number":18,"category":"ITサービス","question":"ある業務システム開発で、iTILが主に扱うものはどれか。","options":{"A":"統計解析だけ","B":"UI設計だけ","C":"ITサービスマネジメント","D":"ソースコード生成"},"answer":"C","explanation":"ITILはITサービスマネジメントのベストプラクティス。"},{"id":"E03Q19","exam":3,"number":19,"category":"セーフティ","question":"ある業務システム開発で、ハザードの説明として適切なのはどれか。","options":{"A":"構成品目","B":"危害を引き起こす潜在的な原因","C":"実際に生じた損害そのもの","D":"品質目標"},"answer":"B","explanation":"ハザード＝危害につながる潜在的原因。"},{"id":"E03Q20","exam":3,"number":20,"category":"セーフティ","question":"ある業務システム開発で、本質安全の考え方として最も近いものはどれか。","options":{"A":"ハザードそのものを除去・低減する","B":"ハザード発生後だけ警告する","C":"バックアップを取るだけ","D":"ログを残すだけ"},"answer":"A","explanation":"危険源そのものを抑える＝本質安全。"},{"id":"E03Q21","exam":3,"number":21,"category":"セーフティ","question":"ある業務システム開発で、機能安全の考え方として最も近いものはどれか。","options":{"A":"危険源を物理的に必ずゼロにする","B":"可用性だけを高める","C":"暗号化だけを行う","D":"安全関連機能によって危害へ至るリスクを低減する"},"answer":"D","explanation":"安全機能によってリスクを許容可能にする。"},{"id":"E03Q22","exam":3,"number":22,"category":"AI品質","question":"ある業務システム開発で、aIシステムの品質評価で適切なものはどれか。","options":{"A":"精度だけ見ればよい","B":"テストは不要","C":"学習データやモデル特性も含めて評価する","D":"通常ソフトと完全に同じ観点だけで十分"},"answer":"C","explanation":"データ・モデル特有の品質も考慮する。"},{"id":"E03Q23","exam":3,"number":23,"category":"IoT品質","question":"ある業務システム開発で、ioTシステムの品質で適切な考え方はどれか。","options":{"A":"品質管理は不要","B":"デバイス・通信・クラウド等を含む全体を考慮する","C":"アプリ画面だけを見る","D":"ローカルPCだけを見る"},"answer":"B","explanation":"複数要素からなるシステム全体で品質を捉える。"},{"id":"E03Q24","exam":3,"number":24,"category":"クラウド品質","question":"ある業務システム開発で、クラウド利用時の品質で考慮すべきものはどれか。","options":{"A":"可用性・セキュリティ・サービス依存性など","B":"障害は起きないので品質活動不要","C":"テスト不要","D":"性能は常に一定"},"answer":"A","explanation":"クラウド固有の依存関係や運用品質も考慮する。"},{"id":"E03Q25","exam":3,"number":25,"category":"品質概念","question":"レビュー会議において、verificationの説明として最も適切なものはどれか。","options":{"A":"運用コストだけを確認する","B":"市場シェアを確認する","C":"利用者のニーズに合う製品かを確認する","D":"成果物が規定要求どおり正しく作られているか確認する"},"answer":"D","explanation":"Verificationは「正しく作っているか」を確認する。Validationは「正しいものを作っているか」。"},{"id":"E03Q26","exam":3,"number":26,"category":"品質概念","question":"レビュー会議において、validationの説明として最も適切なものはどれか。","options":{"A":"欠陥密度を測る","B":"成果物が上位仕様に適合しているかだけを見る","C":"利用者の意図した用途・ニーズを満たすか確認する","D":"構成品目を識別する"},"answer":"C","explanation":"Validationは意図した用途や利用者ニーズを満たすかを確認する。"},{"id":"E03Q27","exam":3,"number":27,"category":"品質モデル","question":"レビュー会議において、通常運用時に信頼性要求を満たして安定して動作する性質はどれか。","options":{"A":"成熟性","B":"可用性","C":"障害許容性","D":"回復性"},"answer":"A","explanation":"平常時＝成熟性。"},{"id":"E03Q28","exam":3,"number":28,"category":"品質モデル","question":"レビュー会議において、障害発生中でも必要な機能を継続できる性質はどれか。","options":{"A":"可用性","B":"障害許容性","C":"回復性","D":"成熟性"},"answer":"B","explanation":"障害中＝障害許容性。"},{"id":"E03Q29","exam":3,"number":29,"category":"品質モデル","question":"レビュー会議において、障害後にデータや状態を復旧できる性質はどれか。","options":{"A":"障害許容性","B":"回復性","C":"成熟性","D":"可用性"},"answer":"B","explanation":"障害後＝回復性。"},{"id":"E03Q30","exam":3,"number":30,"category":"品質モデル","question":"レビュー会議において、必要な時にシステムを利用できる性質はどれか。","options":{"A":"回復性","B":"成熟性","C":"可用性","D":"障害許容性"},"answer":"C","explanation":"利用可能である度合い＝可用性。"},{"id":"E03Q31","exam":3,"number":31,"category":"保守性","question":"レビュー会議において、あるモジュールの変更が他モジュールへ波及しにくい性質はどれか。","options":{"A":"解析性","B":"モジュール性","C":"修正性","D":"試験性"},"answer":"B","explanation":"変更影響の局所化＝モジュール性。"},{"id":"E03Q32","exam":3,"number":32,"category":"保守性","question":"レビュー会議において、障害原因や変更対象を調査しやすい性質はどれか。","options":{"A":"再利用性","B":"修正性","C":"試験性","D":"解析性"},"answer":"D","explanation":"原因・変更箇所を分析しやすい＝解析性。"},{"id":"E03Q33","exam":3,"number":33,"category":"保守性","question":"レビュー会議において、変更後のソフトウェアを効率よくテストできる性質はどれか。","options":{"A":"修正性","B":"試験性","C":"解析性","D":"再利用性"},"answer":"B","explanation":"テストしやすさ＝試験性。"},{"id":"E03Q34","exam":3,"number":34,"category":"セキュリティ","question":"レビュー会議において、許可されていない者による情報閲覧を防ぐ性質はどれか。","options":{"A":"責任追跡性","B":"機密性","C":"インテグリティ","D":"真正性"},"answer":"B","explanation":"見せない＝機密性。"},{"id":"E03Q35","exam":3,"number":35,"category":"セキュリティ","question":"レビュー会議において、権限のない変更・改ざんを防ぐ性質はどれか。","options":{"A":"機密性","B":"インテグリティ","C":"真正性","D":"否認防止性"},"answer":"B","explanation":"変えさせない＝インテグリティ。"},{"id":"E03Q36","exam":3,"number":36,"category":"セキュリティ","question":"レビュー会議において、操作を行った主体を後から追跡できる性質はどれか。","options":{"A":"責任追跡性","B":"否認防止性","C":"機密性","D":"真正性"},"answer":"A","explanation":"誰が行ったか追える＝責任追跡性。"},{"id":"E03Q37","exam":3,"number":37,"category":"セキュリティ","question":"レビュー会議において、利用者が主張どおりの本人であることを確認する性質はどれか。","options":{"A":"否認防止性","B":"インテグリティ","C":"真正性","D":"責任追跡性"},"answer":"C","explanation":"本当に本人か＝真正性。"},{"id":"E03Q38","exam":3,"number":38,"category":"セキュリティ","question":"レビュー会議において、電子的な操作を後から『自分はしていない』と否定できないようにする性質はどれか。","options":{"A":"機密性","B":"真正性","C":"責任追跡性","D":"否認防止性"},"answer":"D","explanation":"行為の否定を防ぐ＝否認防止性。"},{"id":"E03Q39","exam":3,"number":39,"category":"レビュー","question":"レビュー会議において、インスペクションの特徴として最も適切なものはどれか。","options":{"A":"作成者だけで自由に確認する","B":"役割や手順を定め体系的に行う","C":"必ずプログラムを実行する","D":"テスト完了後だけ行う"},"answer":"B","explanation":"インスペクションは比較的形式的なレビュー。"},{"id":"E03Q40","exam":3,"number":40,"category":"レビュー","question":"レビュー会議において、ウォークスルーの特徴として最も適切なものはどれか。","options":{"A":"必ず監査部門が主導する","B":"動的テストの一種である","C":"構成管理の一種である","D":"作成者が説明を主導することが多い"},"answer":"D","explanation":"ウォークスルーは作成者主導で説明・確認する形が代表的。 ---"},{"id":"E04Q01","exam":4,"number":1,"category":"テスト","question":"レビュー会議において、同値分割法の説明として最も適切なものはどれか。","options":{"A":"内部分岐をすべて実行する","B":"無作為値だけを使う","C":"同様の振る舞いが期待される入力集合に分割する","D":"境界値だけを試す"},"answer":"C","explanation":"同値クラスごとに代表値を選ぶ。"},{"id":"E04Q02","exam":4,"number":2,"category":"テスト","question":"入力範囲が1以上100以下のとき、境界値分析で特に有効な組合せはどれか。","options":{"A":"10,20,30,40","B":"25,50,75","C":"1,100","D":"0,1,100,101"},"answer":"D","explanation":"境界の直前・境界・直後を重視する。"},{"id":"E04Q03","exam":4,"number":3,"category":"テスト","question":"レビュー会議において、複数条件の組合せと結果の関係を整理してテストする技法はどれか。","options":{"A":"状態遷移テスト","B":"デシジョンテーブルテスト","C":"命令網羅","D":"探索的テスト"},"answer":"B","explanation":"条件組合せ＝デシジョンテーブル。"},{"id":"E04Q04","exam":4,"number":4,"category":"テスト","question":"レビュー会議において、状態によって同じイベントへの応答が変化するシステムに適した技法はどれか。","options":{"A":"同値分割","B":"分岐網羅","C":"静的解析","D":"状態遷移テスト"},"answer":"D","explanation":"状態と遷移を持つ対象には状態遷移テスト。"},{"id":"E04Q05","exam":4,"number":5,"category":"テスト","question":"レビュー会議において、変更による既存機能への悪影響を確認するテストはどれか。","options":{"A":"負荷テスト","B":"ユーザビリティテスト","C":"受入テスト","D":"回帰テスト"},"answer":"D","explanation":"変更後の副作用確認＝回帰テスト。"},{"id":"E04Q06","exam":4,"number":6,"category":"テスト","question":"レビュー会議において、内部の制御構造を基に網羅率を測るテストはどれか。","options":{"A":"ユーザビリティテスト","B":"ブラックボックステスト","C":"ホワイトボックステスト","D":"受入テスト"},"answer":"C","explanation":"命令・分岐など内部構造に着目＝ホワイトボックス。"},{"id":"E04Q07","exam":4,"number":7,"category":"テスト","question":"レビュー会議において、テストで欠陥が見つからなかった場合の判断として適切なのはどれか。","options":{"A":"欠陥が存在しないことが証明された","B":"品質100%である","C":"実施したテストでは発見されなかっただけである","D":"テストは不要だった"},"answer":"C","explanation":"テストは欠陥の不在を完全には証明できない。"},{"id":"E04Q08","exam":4,"number":8,"category":"品質管理","question":"レビュー会議において、パレート図の主な用途はどれか。","options":{"A":"重要な問題を優先順位付けする","B":"二変数の相関を見る","C":"原因候補を枝状に整理する","D":"時系列変化を監視する"},"answer":"A","explanation":"大きい項目から並べ重点問題を把握する。"},{"id":"E04Q09","exam":4,"number":9,"category":"品質管理","question":"レビュー会議において、特性要因図の主な用途はどれか。","options":{"A":"時系列の管理限界を見る","B":"テストケースを生成する","C":"原因候補を体系的に整理する","D":"頻度順に並べる"},"answer":"C","explanation":"結果と原因候補を魚の骨状に整理する。"},{"id":"E04Q10","exam":4,"number":10,"category":"品質管理","question":"レビュー会議において、散布図の主な用途はどれか。","options":{"A":"構成品目を管理する","B":"二つの変数の関係を観察する","C":"原因候補を階層化する","D":"頻度順に並べる"},"answer":"B","explanation":"二変数間の関係を見る。"},{"id":"E04Q11","exam":4,"number":11,"category":"品質管理","question":"レビュー会議において、管理図の主な用途はどれか。","options":{"A":"プロセスの変動が統計的に安定しているか監視する","B":"機能要求を整理する","C":"コードを自動生成する","D":"レビュー役割を定義する"},"answer":"A","explanation":"管理限界などを用いて工程の安定性を見る。"},{"id":"E04Q12","exam":4,"number":12,"category":"品質コスト","question":"レビュー会議において、品質教育や標準化活動に要する費用はどれか。","options":{"A":"評価コスト","B":"内部失敗コスト","C":"外部失敗コスト","D":"予防コスト"},"answer":"D","explanation":"不良を未然に防ぐ活動＝予防コスト。"},{"id":"E04Q13","exam":4,"number":13,"category":"品質コスト","question":"レビュー会議において、出荷前の検査・テストに要する費用はどれか。","options":{"A":"内部失敗コスト","B":"外部失敗コスト","C":"予防コスト","D":"評価コスト"},"answer":"D","explanation":"適合性を評価する活動＝評価コスト。"},{"id":"E04Q14","exam":4,"number":14,"category":"品質コスト","question":"レビュー会議において、出荷前に発見された欠陥の修正費用はどれか。","options":{"A":"外部失敗コスト","B":"予防コスト","C":"評価コスト","D":"内部失敗コスト"},"answer":"D","explanation":"顧客へ渡る前の失敗＝内部失敗コスト。"},{"id":"E04Q15","exam":4,"number":15,"category":"品質コスト","question":"レビュー会議において、市場で発生した障害・クレームへの対応費用はどれか。","options":{"A":"予防コスト","B":"評価コスト","C":"内部失敗コスト","D":"外部失敗コスト"},"answer":"D","explanation":"顧客へ渡った後の失敗＝外部失敗コスト。"},{"id":"E04Q16","exam":4,"number":16,"category":"メトリクス","question":"レビュー会議において、gQMの正しい展開順序はどれか。","options":{"A":"Goal→Question→Metric","B":"Graph→Question→Measure","C":"Goal→Query→Model","D":"Goal→Quality→Metric"},"answer":"A","explanation":"GQM = Goal, Question, Metric。"},{"id":"E04Q17","exam":4,"number":17,"category":"メトリクス","question":"レビュー会議において、欠陥密度の例として最も適切なものはどれか。","options":{"A":"CPU使用率","B":"平均給与","C":"KLOC当たりの欠陥数","D":"1日当たり勤務時間"},"answer":"C","explanation":"規模当たり欠陥数が代表例。"},{"id":"E04Q18","exam":4,"number":18,"category":"信頼性指標","question":"レビュー会議において、mTBFが表すものはどれか。","options":{"A":"平均テスト時間","B":"平均修復時間","C":"平均故障間隔","D":"平均応答時間"},"answer":"C","explanation":"MTBF = Mean Time Between Failures。"},{"id":"E04Q19","exam":4,"number":19,"category":"信頼性指標","question":"レビュー会議において、mTTRが一般に表すものはどれか。","options":{"A":"平均修復時間","B":"平均故障間隔","C":"平均レビュー時間","D":"平均要求数"},"answer":"A","explanation":"MTTR = Mean Time To Repair/Recovery。"},{"id":"E04Q20","exam":4,"number":20,"category":"統計","question":"1つの目的変数を複数の説明変数から説明・予測する代表的手法はどれか。","options":{"A":"クラスター分析","B":"因子分析","C":"パレート分析","D":"重回帰分析"},"answer":"D","explanation":"複数説明変数→1目的変数＝重回帰分析。"},{"id":"E04Q21","exam":4,"number":21,"category":"統計","question":"レビュー会議において、似た特徴を持つ対象をグループ化する手法はどれか。","options":{"A":"因子分析","B":"管理図","C":"重回帰分析","D":"クラスター分析"},"answer":"D","explanation":"類似対象のグループ化＝クラスター分析。"},{"id":"E04Q22","exam":4,"number":22,"category":"統計","question":"レビュー会議において、観測変数の背後にある潜在的な因子を探る手法はどれか。","options":{"A":"散布図","B":"重回帰分析","C":"クラスター分析","D":"因子分析"},"answer":"D","explanation":"潜在因子の探索＝因子分析。"},{"id":"E04Q23","exam":4,"number":23,"category":"構成管理","question":"レビュー会議において、ベースラインの説明として適切なのはどれか。","options":{"A":"正式に合意され変更管理の対象となる基準状態","B":"最新ファイルなら何でもよい","C":"個人PCの一時保存","D":"バックアップだけを指す"},"answer":"A","explanation":"ベースライン変更は正式な変更管理下で行う。"},{"id":"E04Q24","exam":4,"number":24,"category":"構成管理","question":"レビュー会議において、構成管理で不適切な行為はどれか。","options":{"A":"変更履歴を記録する","B":"担当者個人が無手続でベースライン変更を確定する","C":"リリース対象を管理する","D":"構成品目を識別する"},"answer":"B","explanation":"ベースライン変更は権限ある仕組みで統制する。"},{"id":"E04Q25","exam":4,"number":25,"category":"品質計画","question":"レビュー会議において、品質計画について最も適切なものはどれか。","options":{"A":"合否基準を含めない","B":"品質評価計画を含めない","C":"一度作れば固定する","D":"要求やプロセス変更に応じて見直す"},"answer":"D","explanation":"品質計画は状況変化に応じて更新する。"},{"id":"E04Q26","exam":4,"number":26,"category":"改善","question":"レビュー会議において、根本原因分析の目的として最も適切なものはどれか。","options":{"A":"欠陥件数を減らして記録する","B":"責任者を処罰する","C":"根本原因を特定し再発防止につなげる","D":"障害を一時回避するだけ"},"answer":"C","explanation":"原因の深掘りと再発防止が目的。"},{"id":"E04Q27","exam":4,"number":27,"category":"改善","question":"レビュー会議において、pDCAの正しい順序はどれか。","options":{"A":"Plan→Check→Do→Act","B":"Plan→Do→Check→Act","C":"Do→Plan→Act→Check","D":"Plan→Act→Do→Check"},"answer":"B","explanation":"Plan, Do, Check, Act。"},{"id":"E04Q28","exam":4,"number":28,"category":"リスク","question":"レビュー会議において、リスクベースドテストの考え方として適切なのはどれか。","options":{"A":"発生可能性や影響度を考慮して優先度を決める","B":"テストを行わずリスク評価だけする","C":"担当者の好みだけで決める","D":"全機能へ同量のテストを割り当てる"},"answer":"A","explanation":"高リスク領域へ重点的にテスト資源を配分する。"},{"id":"E04Q29","exam":4,"number":29,"category":"CI/CD","question":"レビュー会議において、cIの説明として最も適切なものはどれか。","options":{"A":"統合を手作業中心にする","B":"自動化後は結果確認不要","C":"変更を頻繁に統合しビルドやテスト等を自動化する","D":"本番デプロイだけを指す"},"answer":"C","explanation":"CIは継続的統合。自動化しても結果確認は必要。"},{"id":"E04Q30","exam":4,"number":30,"category":"ITサービス","question":"レビュー会議において、iTILが主に扱うものはどれか。","options":{"A":"UI設計だけ","B":"ITサービスマネジメント","C":"ソースコード生成","D":"統計解析だけ"},"answer":"B","explanation":"ITILはITサービスマネジメントのベストプラクティス。"},{"id":"E04Q31","exam":4,"number":31,"category":"セーフティ","question":"レビュー会議において、ハザードの説明として適切なのはどれか。","options":{"A":"危害を引き起こす潜在的な原因","B":"実際に生じた損害そのもの","C":"品質目標","D":"構成品目"},"answer":"A","explanation":"ハザード＝危害につながる潜在的原因。"},{"id":"E04Q32","exam":4,"number":32,"category":"セーフティ","question":"レビュー会議において、本質安全の考え方として最も近いものはどれか。","options":{"A":"ハザード発生後だけ警告する","B":"バックアップを取るだけ","C":"ログを残すだけ","D":"ハザードそのものを除去・低減する"},"answer":"D","explanation":"危険源そのものを抑える＝本質安全。"},{"id":"E04Q33","exam":4,"number":33,"category":"セーフティ","question":"レビュー会議において、機能安全の考え方として最も近いものはどれか。","options":{"A":"可用性だけを高める","B":"暗号化だけを行う","C":"安全関連機能によって危害へ至るリスクを低減する","D":"危険源を物理的に必ずゼロにする"},"answer":"C","explanation":"安全機能によってリスクを許容可能にする。"},{"id":"E04Q34","exam":4,"number":34,"category":"AI品質","question":"レビュー会議において、aIシステムの品質評価で適切なものはどれか。","options":{"A":"テストは不要","B":"学習データやモデル特性も含めて評価する","C":"通常ソフトと完全に同じ観点だけで十分","D":"精度だけ見ればよい"},"answer":"B","explanation":"データ・モデル特有の品質も考慮する。"},{"id":"E04Q35","exam":4,"number":35,"category":"IoT品質","question":"レビュー会議において、ioTシステムの品質で適切な考え方はどれか。","options":{"A":"デバイス・通信・クラウド等を含む全体を考慮する","B":"アプリ画面だけを見る","C":"ローカルPCだけを見る","D":"品質管理は不要"},"answer":"A","explanation":"複数要素からなるシステム全体で品質を捉える。"},{"id":"E04Q36","exam":4,"number":36,"category":"クラウド品質","question":"レビュー会議において、クラウド利用時の品質で考慮すべきものはどれか。","options":{"A":"障害は起きないので品質活動不要","B":"テスト不要","C":"性能は常に一定","D":"可用性・セキュリティ・サービス依存性など"},"answer":"D","explanation":"クラウド固有の依存関係や運用品質も考慮する。"},{"id":"E04Q37","exam":4,"number":37,"category":"品質概念","question":"運用中のWebサービスについて、verificationの説明として最も適切なものはどれか。","options":{"A":"市場シェアを確認する","B":"利用者のニーズに合う製品かを確認する","C":"成果物が規定要求どおり正しく作られているか確認する","D":"運用コストだけを確認する"},"answer":"C","explanation":"Verificationは「正しく作っているか」を確認する。Validationは「正しいものを作っているか」。"},{"id":"E04Q38","exam":4,"number":38,"category":"品質概念","question":"運用中のWebサービスについて、validationの説明として最も適切なものはどれか。","options":{"A":"成果物が上位仕様に適合しているかだけを見る","B":"利用者の意図した用途・ニーズを満たすか確認する","C":"構成品目を識別する","D":"欠陥密度を測る"},"answer":"B","explanation":"Validationは意図した用途や利用者ニーズを満たすかを確認する。"},{"id":"E04Q39","exam":4,"number":39,"category":"品質モデル","question":"運用中のWebサービスについて、通常運用時に信頼性要求を満たして安定して動作する性質はどれか。","options":{"A":"可用性","B":"障害許容性","C":"回復性","D":"成熟性"},"answer":"D","explanation":"平常時＝成熟性。"},{"id":"E04Q40","exam":4,"number":40,"category":"品質モデル","question":"運用中のWebサービスについて、障害発生中でも必要な機能を継続できる性質はどれか。","options":{"A":"障害許容性","B":"回復性","C":"成熟性","D":"可用性"},"answer":"A","explanation":"障害中＝障害許容性。 ---"},{"id":"E05Q01","exam":5,"number":1,"category":"品質モデル","question":"運用中のWebサービスについて、障害後にデータや状態を復旧できる性質はどれか。","options":{"A":"回復性","B":"成熟性","C":"可用性","D":"障害許容性"},"answer":"A","explanation":"障害後＝回復性。"},{"id":"E05Q02","exam":5,"number":2,"category":"品質モデル","question":"運用中のWebサービスについて、必要な時にシステムを利用できる性質はどれか。","options":{"A":"成熟性","B":"可用性","C":"障害許容性","D":"回復性"},"answer":"B","explanation":"利用可能である度合い＝可用性。"},{"id":"E05Q03","exam":5,"number":3,"category":"保守性","question":"運用中のWebサービスについて、あるモジュールの変更が他モジュールへ波及しにくい性質はどれか。","options":{"A":"モジュール性","B":"修正性","C":"試験性","D":"解析性"},"answer":"A","explanation":"変更影響の局所化＝モジュール性。"},{"id":"E05Q04","exam":5,"number":4,"category":"保守性","question":"運用中のWebサービスについて、障害原因や変更対象を調査しやすい性質はどれか。","options":{"A":"修正性","B":"試験性","C":"解析性","D":"再利用性"},"answer":"C","explanation":"原因・変更箇所を分析しやすい＝解析性。"},{"id":"E05Q05","exam":5,"number":5,"category":"保守性","question":"運用中のWebサービスについて、変更後のソフトウェアを効率よくテストできる性質はどれか。","options":{"A":"試験性","B":"解析性","C":"再利用性","D":"修正性"},"answer":"A","explanation":"テストしやすさ＝試験性。"},{"id":"E05Q06","exam":5,"number":6,"category":"セキュリティ","question":"運用中のWebサービスについて、許可されていない者による情報閲覧を防ぐ性質はどれか。","options":{"A":"機密性","B":"インテグリティ","C":"真正性","D":"責任追跡性"},"answer":"A","explanation":"見せない＝機密性。"},{"id":"E05Q07","exam":5,"number":7,"category":"セキュリティ","question":"運用中のWebサービスについて、権限のない変更・改ざんを防ぐ性質はどれか。","options":{"A":"インテグリティ","B":"真正性","C":"否認防止性","D":"機密性"},"answer":"A","explanation":"変えさせない＝インテグリティ。"},{"id":"E05Q08","exam":5,"number":8,"category":"セキュリティ","question":"運用中のWebサービスについて、操作を行った主体を後から追跡できる性質はどれか。","options":{"A":"否認防止性","B":"機密性","C":"真正性","D":"責任追跡性"},"answer":"D","explanation":"誰が行ったか追える＝責任追跡性。"},{"id":"E05Q09","exam":5,"number":9,"category":"セキュリティ","question":"運用中のWebサービスについて、利用者が主張どおりの本人であることを確認する性質はどれか。","options":{"A":"インテグリティ","B":"真正性","C":"責任追跡性","D":"否認防止性"},"answer":"B","explanation":"本当に本人か＝真正性。"},{"id":"E05Q10","exam":5,"number":10,"category":"セキュリティ","question":"運用中のWebサービスについて、電子的な操作を後から『自分はしていない』と否定できないようにする性質はどれか。","options":{"A":"真正性","B":"責任追跡性","C":"否認防止性","D":"機密性"},"answer":"C","explanation":"行為の否定を防ぐ＝否認防止性。"},{"id":"E05Q11","exam":5,"number":11,"category":"レビュー","question":"運用中のWebサービスについて、インスペクションの特徴として最も適切なものはどれか。","options":{"A":"役割や手順を定め体系的に行う","B":"必ずプログラムを実行する","C":"テスト完了後だけ行う","D":"作成者だけで自由に確認する"},"answer":"A","explanation":"インスペクションは比較的形式的なレビュー。"},{"id":"E05Q12","exam":5,"number":12,"category":"レビュー","question":"運用中のWebサービスについて、ウォークスルーの特徴として最も適切なものはどれか。","options":{"A":"動的テストの一種である","B":"構成管理の一種である","C":"作成者が説明を主導することが多い","D":"必ず監査部門が主導する"},"answer":"C","explanation":"ウォークスルーは作成者主導で説明・確認する形が代表的。"},{"id":"E05Q13","exam":5,"number":13,"category":"テスト","question":"運用中のWebサービスについて、同値分割法の説明として最も適切なものはどれか。","options":{"A":"無作為値だけを使う","B":"同様の振る舞いが期待される入力集合に分割する","C":"境界値だけを試す","D":"内部分岐をすべて実行する"},"answer":"B","explanation":"同値クラスごとに代表値を選ぶ。"},{"id":"E05Q14","exam":5,"number":14,"category":"テスト","question":"入力範囲が1以上100以下のとき、境界値分析で特に有効な組合せはどれか。","options":{"A":"25,50,75","B":"1,100","C":"0,1,100,101","D":"10,20,30,40"},"answer":"C","explanation":"境界の直前・境界・直後を重視する。"},{"id":"E05Q15","exam":5,"number":15,"category":"テスト","question":"運用中のWebサービスについて、複数条件の組合せと結果の関係を整理してテストする技法はどれか。","options":{"A":"デシジョンテーブルテスト","B":"命令網羅","C":"探索的テスト","D":"状態遷移テスト"},"answer":"A","explanation":"条件組合せ＝デシジョンテーブル。"},{"id":"E05Q16","exam":5,"number":16,"category":"テスト","question":"運用中のWebサービスについて、状態によって同じイベントへの応答が変化するシステムに適した技法はどれか。","options":{"A":"分岐網羅","B":"静的解析","C":"状態遷移テスト","D":"同値分割"},"answer":"C","explanation":"状態と遷移を持つ対象には状態遷移テスト。"},{"id":"E05Q17","exam":5,"number":17,"category":"テスト","question":"運用中のWebサービスについて、変更による既存機能への悪影響を確認するテストはどれか。","options":{"A":"ユーザビリティテスト","B":"受入テスト","C":"回帰テスト","D":"負荷テスト"},"answer":"C","explanation":"変更後の副作用確認＝回帰テスト。"},{"id":"E05Q18","exam":5,"number":18,"category":"テスト","question":"運用中のWebサービスについて、内部の制御構造を基に網羅率を測るテストはどれか。","options":{"A":"ブラックボックステスト","B":"ホワイトボックステスト","C":"受入テスト","D":"ユーザビリティテスト"},"answer":"B","explanation":"命令・分岐など内部構造に着目＝ホワイトボックス。"},{"id":"E05Q19","exam":5,"number":19,"category":"テスト","question":"運用中のWebサービスについて、テストで欠陥が見つからなかった場合の判断として適切なのはどれか。","options":{"A":"品質100%である","B":"実施したテストでは発見されなかっただけである","C":"テストは不要だった","D":"欠陥が存在しないことが証明された"},"answer":"B","explanation":"テストは欠陥の不在を完全には証明できない。"},{"id":"E05Q20","exam":5,"number":20,"category":"品質管理","question":"運用中のWebサービスについて、パレート図の主な用途はどれか。","options":{"A":"二変数の相関を見る","B":"原因候補を枝状に整理する","C":"時系列変化を監視する","D":"重要な問題を優先順位付けする"},"answer":"D","explanation":"大きい項目から並べ重点問題を把握する。"},{"id":"E05Q21","exam":5,"number":21,"category":"品質管理","question":"運用中のWebサービスについて、特性要因図の主な用途はどれか。","options":{"A":"テストケースを生成する","B":"原因候補を体系的に整理する","C":"頻度順に並べる","D":"時系列の管理限界を見る"},"answer":"B","explanation":"結果と原因候補を魚の骨状に整理する。"},{"id":"E05Q22","exam":5,"number":22,"category":"品質管理","question":"運用中のWebサービスについて、散布図の主な用途はどれか。","options":{"A":"二つの変数の関係を観察する","B":"原因候補を階層化する","C":"頻度順に並べる","D":"構成品目を管理する"},"answer":"A","explanation":"二変数間の関係を見る。"},{"id":"E05Q23","exam":5,"number":23,"category":"品質管理","question":"運用中のWebサービスについて、管理図の主な用途はどれか。","options":{"A":"機能要求を整理する","B":"コードを自動生成する","C":"レビュー役割を定義する","D":"プロセスの変動が統計的に安定しているか監視する"},"answer":"D","explanation":"管理限界などを用いて工程の安定性を見る。"},{"id":"E05Q24","exam":5,"number":24,"category":"品質コスト","question":"運用中のWebサービスについて、品質教育や標準化活動に要する費用はどれか。","options":{"A":"内部失敗コスト","B":"外部失敗コスト","C":"予防コスト","D":"評価コスト"},"answer":"C","explanation":"不良を未然に防ぐ活動＝予防コスト。"},{"id":"E05Q25","exam":5,"number":25,"category":"品質コスト","question":"運用中のWebサービスについて、出荷前の検査・テストに要する費用はどれか。","options":{"A":"外部失敗コスト","B":"予防コスト","C":"評価コスト","D":"内部失敗コスト"},"answer":"C","explanation":"適合性を評価する活動＝評価コスト。"},{"id":"E05Q26","exam":5,"number":26,"category":"品質コスト","question":"運用中のWebサービスについて、出荷前に発見された欠陥の修正費用はどれか。","options":{"A":"予防コスト","B":"評価コスト","C":"内部失敗コスト","D":"外部失敗コスト"},"answer":"C","explanation":"顧客へ渡る前の失敗＝内部失敗コスト。"},{"id":"E05Q27","exam":5,"number":27,"category":"品質コスト","question":"運用中のWebサービスについて、市場で発生した障害・クレームへの対応費用はどれか。","options":{"A":"評価コスト","B":"内部失敗コスト","C":"外部失敗コスト","D":"予防コスト"},"answer":"C","explanation":"顧客へ渡った後の失敗＝外部失敗コスト。"},{"id":"E05Q28","exam":5,"number":28,"category":"メトリクス","question":"運用中のWebサービスについて、gQMの正しい展開順序はどれか。","options":{"A":"Graph→Question→Measure","B":"Goal→Query→Model","C":"Goal→Quality→Metric","D":"Goal→Question→Metric"},"answer":"D","explanation":"GQM = Goal, Question, Metric。"},{"id":"E05Q29","exam":5,"number":29,"category":"メトリクス","question":"運用中のWebサービスについて、欠陥密度の例として最も適切なものはどれか。","options":{"A":"平均給与","B":"KLOC当たりの欠陥数","C":"1日当たり勤務時間","D":"CPU使用率"},"answer":"B","explanation":"規模当たり欠陥数が代表例。"},{"id":"E05Q30","exam":5,"number":30,"category":"信頼性指標","question":"運用中のWebサービスについて、mTBFが表すものはどれか。","options":{"A":"平均修復時間","B":"平均故障間隔","C":"平均応答時間","D":"平均テスト時間"},"answer":"B","explanation":"MTBF = Mean Time Between Failures。"},{"id":"E05Q31","exam":5,"number":31,"category":"信頼性指標","question":"運用中のWebサービスについて、mTTRが一般に表すものはどれか。","options":{"A":"平均故障間隔","B":"平均レビュー時間","C":"平均要求数","D":"平均修復時間"},"answer":"D","explanation":"MTTR = Mean Time To Repair/Recovery。"},{"id":"E05Q32","exam":5,"number":32,"category":"統計","question":"1つの目的変数を複数の説明変数から説明・予測する代表的手法はどれか。","options":{"A":"因子分析","B":"パレート分析","C":"重回帰分析","D":"クラスター分析"},"answer":"C","explanation":"複数説明変数→1目的変数＝重回帰分析。"},{"id":"E05Q33","exam":5,"number":33,"category":"統計","question":"運用中のWebサービスについて、似た特徴を持つ対象をグループ化する手法はどれか。","options":{"A":"管理図","B":"重回帰分析","C":"クラスター分析","D":"因子分析"},"answer":"C","explanation":"類似対象のグループ化＝クラスター分析。"},{"id":"E05Q34","exam":5,"number":34,"category":"統計","question":"運用中のWebサービスについて、観測変数の背後にある潜在的な因子を探る手法はどれか。","options":{"A":"重回帰分析","B":"クラスター分析","C":"因子分析","D":"散布図"},"answer":"C","explanation":"潜在因子の探索＝因子分析。"},{"id":"E05Q35","exam":5,"number":35,"category":"構成管理","question":"運用中のWebサービスについて、ベースラインの説明として適切なのはどれか。","options":{"A":"最新ファイルなら何でもよい","B":"個人PCの一時保存","C":"バックアップだけを指す","D":"正式に合意され変更管理の対象となる基準状態"},"answer":"D","explanation":"ベースライン変更は正式な変更管理下で行う。"},{"id":"E05Q36","exam":5,"number":36,"category":"構成管理","question":"運用中のWebサービスについて、構成管理で不適切な行為はどれか。","options":{"A":"担当者個人が無手続でベースライン変更を確定する","B":"リリース対象を管理する","C":"構成品目を識別する","D":"変更履歴を記録する"},"answer":"A","explanation":"ベースライン変更は権限ある仕組みで統制する。"},{"id":"E05Q37","exam":5,"number":37,"category":"品質計画","question":"運用中のWebサービスについて、品質計画について最も適切なものはどれか。","options":{"A":"品質評価計画を含めない","B":"一度作れば固定する","C":"要求やプロセス変更に応じて見直す","D":"合否基準を含めない"},"answer":"C","explanation":"品質計画は状況変化に応じて更新する。"},{"id":"E05Q38","exam":5,"number":38,"category":"改善","question":"運用中のWebサービスについて、根本原因分析の目的として最も適切なものはどれか。","options":{"A":"責任者を処罰する","B":"根本原因を特定し再発防止につなげる","C":"障害を一時回避するだけ","D":"欠陥件数を減らして記録する"},"answer":"B","explanation":"原因の深掘りと再発防止が目的。"},{"id":"E05Q39","exam":5,"number":39,"category":"改善","question":"運用中のWebサービスについて、pDCAの正しい順序はどれか。","options":{"A":"Plan→Do→Check→Act","B":"Do→Plan→Act→Check","C":"Plan→Act→Do→Check","D":"Plan→Check→Do→Act"},"answer":"A","explanation":"Plan, Do, Check, Act。"},{"id":"E05Q40","exam":5,"number":40,"category":"リスク","question":"運用中のWebサービスについて、リスクベースドテストの考え方として適切なのはどれか。","options":{"A":"テストを行わずリスク評価だけする","B":"担当者の好みだけで決める","C":"全機能へ同量のテストを割り当てる","D":"発生可能性や影響度を考慮して優先度を決める"},"answer":"D","explanation":"高リスク領域へ重点的にテスト資源を配分する。 ---"},{"id":"E06Q01","exam":6,"number":1,"category":"CI/CD","question":"運用中のWebサービスについて、cIの説明として最も適切なものはどれか。","options":{"A":"自動化後は結果確認不要","B":"変更を頻繁に統合しビルドやテスト等を自動化する","C":"本番デプロイだけを指す","D":"統合を手作業中心にする"},"answer":"B","explanation":"CIは継続的統合。自動化しても結果確認は必要。"},{"id":"E06Q02","exam":6,"number":2,"category":"ITサービス","question":"運用中のWebサービスについて、iTILが主に扱うものはどれか。","options":{"A":"ITサービスマネジメント","B":"ソースコード生成","C":"統計解析だけ","D":"UI設計だけ"},"answer":"A","explanation":"ITILはITサービスマネジメントのベストプラクティス。"},{"id":"E06Q03","exam":6,"number":3,"category":"セーフティ","question":"運用中のWebサービスについて、ハザードの説明として適切なのはどれか。","options":{"A":"実際に生じた損害そのもの","B":"品質目標","C":"構成品目","D":"危害を引き起こす潜在的な原因"},"answer":"D","explanation":"ハザード＝危害につながる潜在的原因。"},{"id":"E06Q04","exam":6,"number":4,"category":"セーフティ","question":"運用中のWebサービスについて、本質安全の考え方として最も近いものはどれか。","options":{"A":"バックアップを取るだけ","B":"ログを残すだけ","C":"ハザードそのものを除去・低減する","D":"ハザード発生後だけ警告する"},"answer":"C","explanation":"危険源そのものを抑える＝本質安全。"},{"id":"E06Q05","exam":6,"number":5,"category":"セーフティ","question":"運用中のWebサービスについて、機能安全の考え方として最も近いものはどれか。","options":{"A":"暗号化だけを行う","B":"安全関連機能によって危害へ至るリスクを低減する","C":"危険源を物理的に必ずゼロにする","D":"可用性だけを高める"},"answer":"B","explanation":"安全機能によってリスクを許容可能にする。"},{"id":"E06Q06","exam":6,"number":6,"category":"AI品質","question":"運用中のWebサービスについて、aIシステムの品質評価で適切なものはどれか。","options":{"A":"学習データやモデル特性も含めて評価する","B":"通常ソフトと完全に同じ観点だけで十分","C":"精度だけ見ればよい","D":"テストは不要"},"answer":"A","explanation":"データ・モデル特有の品質も考慮する。"},{"id":"E06Q07","exam":6,"number":7,"category":"IoT品質","question":"運用中のWebサービスについて、ioTシステムの品質で適切な考え方はどれか。","options":{"A":"アプリ画面だけを見る","B":"ローカルPCだけを見る","C":"品質管理は不要","D":"デバイス・通信・クラウド等を含む全体を考慮する"},"answer":"D","explanation":"複数要素からなるシステム全体で品質を捉える。"},{"id":"E06Q08","exam":6,"number":8,"category":"クラウド品質","question":"運用中のWebサービスについて、クラウド利用時の品質で考慮すべきものはどれか。","options":{"A":"テスト不要","B":"性能は常に一定","C":"可用性・セキュリティ・サービス依存性など","D":"障害は起きないので品質活動不要"},"answer":"C","explanation":"クラウド固有の依存関係や運用品質も考慮する。"},{"id":"E06Q09","exam":6,"number":9,"category":"品質概念","question":"品質保証担当者が判断する場合、verificationの説明として最も適切なものはどれか。","options":{"A":"利用者のニーズに合う製品かを確認する","B":"成果物が規定要求どおり正しく作られているか確認する","C":"運用コストだけを確認する","D":"市場シェアを確認する"},"answer":"B","explanation":"Verificationは「正しく作っているか」を確認する。Validationは「正しいものを作っているか」。"},{"id":"E06Q10","exam":6,"number":10,"category":"品質概念","question":"品質保証担当者が判断する場合、validationの説明として最も適切なものはどれか。","options":{"A":"利用者の意図した用途・ニーズを満たすか確認する","B":"構成品目を識別する","C":"欠陥密度を測る","D":"成果物が上位仕様に適合しているかだけを見る"},"answer":"A","explanation":"Validationは意図した用途や利用者ニーズを満たすかを確認する。"},{"id":"E06Q11","exam":6,"number":11,"category":"品質モデル","question":"品質保証担当者が判断する場合、通常運用時に信頼性要求を満たして安定して動作する性質はどれか。","options":{"A":"障害許容性","B":"回復性","C":"成熟性","D":"可用性"},"answer":"C","explanation":"平常時＝成熟性。"},{"id":"E06Q12","exam":6,"number":12,"category":"品質モデル","question":"品質保証担当者が判断する場合、障害発生中でも必要な機能を継続できる性質はどれか。","options":{"A":"回復性","B":"成熟性","C":"可用性","D":"障害許容性"},"answer":"D","explanation":"障害中＝障害許容性。"},{"id":"E06Q13","exam":6,"number":13,"category":"品質モデル","question":"品質保証担当者が判断する場合、障害後にデータや状態を復旧できる性質はどれか。","options":{"A":"成熟性","B":"可用性","C":"障害許容性","D":"回復性"},"answer":"D","explanation":"障害後＝回復性。"},{"id":"E06Q14","exam":6,"number":14,"category":"品質モデル","question":"品質保証担当者が判断する場合、必要な時にシステムを利用できる性質はどれか。","options":{"A":"可用性","B":"障害許容性","C":"回復性","D":"成熟性"},"answer":"A","explanation":"利用可能である度合い＝可用性。"},{"id":"E06Q15","exam":6,"number":15,"category":"保守性","question":"品質保証担当者が判断する場合、あるモジュールの変更が他モジュールへ波及しにくい性質はどれか。","options":{"A":"修正性","B":"試験性","C":"解析性","D":"モジュール性"},"answer":"D","explanation":"変更影響の局所化＝モジュール性。"},{"id":"E06Q16","exam":6,"number":16,"category":"保守性","question":"品質保証担当者が判断する場合、障害原因や変更対象を調査しやすい性質はどれか。","options":{"A":"試験性","B":"解析性","C":"再利用性","D":"修正性"},"answer":"B","explanation":"原因・変更箇所を分析しやすい＝解析性。"},{"id":"E06Q17","exam":6,"number":17,"category":"保守性","question":"品質保証担当者が判断する場合、変更後のソフトウェアを効率よくテストできる性質はどれか。","options":{"A":"解析性","B":"再利用性","C":"修正性","D":"試験性"},"answer":"D","explanation":"テストしやすさ＝試験性。"},{"id":"E06Q18","exam":6,"number":18,"category":"セキュリティ","question":"品質保証担当者が判断する場合、許可されていない者による情報閲覧を防ぐ性質はどれか。","options":{"A":"インテグリティ","B":"真正性","C":"責任追跡性","D":"機密性"},"answer":"D","explanation":"見せない＝機密性。"},{"id":"E06Q19","exam":6,"number":19,"category":"セキュリティ","question":"品質保証担当者が判断する場合、権限のない変更・改ざんを防ぐ性質はどれか。","options":{"A":"真正性","B":"否認防止性","C":"機密性","D":"インテグリティ"},"answer":"D","explanation":"変えさせない＝インテグリティ。"},{"id":"E06Q20","exam":6,"number":20,"category":"セキュリティ","question":"品質保証担当者が判断する場合、操作を行った主体を後から追跡できる性質はどれか。","options":{"A":"機密性","B":"真正性","C":"責任追跡性","D":"否認防止性"},"answer":"C","explanation":"誰が行ったか追える＝責任追跡性。"},{"id":"E06Q21","exam":6,"number":21,"category":"セキュリティ","question":"品質保証担当者が判断する場合、利用者が主張どおりの本人であることを確認する性質はどれか。","options":{"A":"真正性","B":"責任追跡性","C":"否認防止性","D":"インテグリティ"},"answer":"A","explanation":"本当に本人か＝真正性。"},{"id":"E06Q22","exam":6,"number":22,"category":"セキュリティ","question":"品質保証担当者が判断する場合、電子的な操作を後から『自分はしていない』と否定できないようにする性質はどれか。","options":{"A":"責任追跡性","B":"否認防止性","C":"機密性","D":"真正性"},"answer":"B","explanation":"行為の否定を防ぐ＝否認防止性。"},{"id":"E06Q23","exam":6,"number":23,"category":"レビュー","question":"品質保証担当者が判断する場合、インスペクションの特徴として最も適切なものはどれか。","options":{"A":"必ずプログラムを実行する","B":"テスト完了後だけ行う","C":"作成者だけで自由に確認する","D":"役割や手順を定め体系的に行う"},"answer":"D","explanation":"インスペクションは比較的形式的なレビュー。"},{"id":"E06Q24","exam":6,"number":24,"category":"レビュー","question":"品質保証担当者が判断する場合、ウォークスルーの特徴として最も適切なものはどれか。","options":{"A":"構成管理の一種である","B":"作成者が説明を主導することが多い","C":"必ず監査部門が主導する","D":"動的テストの一種である"},"answer":"B","explanation":"ウォークスルーは作成者主導で説明・確認する形が代表的。"},{"id":"E06Q25","exam":6,"number":25,"category":"テスト","question":"品質保証担当者が判断する場合、同値分割法の説明として最も適切なものはどれか。","options":{"A":"同様の振る舞いが期待される入力集合に分割する","B":"境界値だけを試す","C":"内部分岐をすべて実行する","D":"無作為値だけを使う"},"answer":"A","explanation":"同値クラスごとに代表値を選ぶ。"},{"id":"E06Q26","exam":6,"number":26,"category":"テスト","question":"入力範囲が1以上100以下のとき、境界値分析で特に有効な組合せはどれか。","options":{"A":"1,100","B":"0,1,100,101","C":"10,20,30,40","D":"25,50,75"},"answer":"B","explanation":"境界の直前・境界・直後を重視する。"},{"id":"E06Q27","exam":6,"number":27,"category":"テスト","question":"品質保証担当者が判断する場合、複数条件の組合せと結果の関係を整理してテストする技法はどれか。","options":{"A":"命令網羅","B":"探索的テスト","C":"状態遷移テスト","D":"デシジョンテーブルテスト"},"answer":"D","explanation":"条件組合せ＝デシジョンテーブル。"},{"id":"E06Q28","exam":6,"number":28,"category":"テスト","question":"品質保証担当者が判断する場合、状態によって同じイベントへの応答が変化するシステムに適した技法はどれか。","options":{"A":"静的解析","B":"状態遷移テスト","C":"同値分割","D":"分岐網羅"},"answer":"B","explanation":"状態と遷移を持つ対象には状態遷移テスト。"},{"id":"E06Q29","exam":6,"number":29,"category":"テスト","question":"品質保証担当者が判断する場合、変更による既存機能への悪影響を確認するテストはどれか。","options":{"A":"受入テスト","B":"回帰テスト","C":"負荷テスト","D":"ユーザビリティテスト"},"answer":"B","explanation":"変更後の副作用確認＝回帰テスト。"},{"id":"E06Q30","exam":6,"number":30,"category":"テスト","question":"品質保証担当者が判断する場合、内部の制御構造を基に網羅率を測るテストはどれか。","options":{"A":"ホワイトボックステスト","B":"受入テスト","C":"ユーザビリティテスト","D":"ブラックボックステスト"},"answer":"A","explanation":"命令・分岐など内部構造に着目＝ホワイトボックス。"},{"id":"E06Q31","exam":6,"number":31,"category":"テスト","question":"品質保証担当者が判断する場合、テストで欠陥が見つからなかった場合の判断として適切なのはどれか。","options":{"A":"実施したテストでは発見されなかっただけである","B":"テストは不要だった","C":"欠陥が存在しないことが証明された","D":"品質100%である"},"answer":"A","explanation":"テストは欠陥の不在を完全には証明できない。"},{"id":"E06Q32","exam":6,"number":32,"category":"品質管理","question":"品質保証担当者が判断する場合、パレート図の主な用途はどれか。","options":{"A":"原因候補を枝状に整理する","B":"時系列変化を監視する","C":"重要な問題を優先順位付けする","D":"二変数の相関を見る"},"answer":"C","explanation":"大きい項目から並べ重点問題を把握する。"},{"id":"E06Q33","exam":6,"number":33,"category":"品質管理","question":"品質保証担当者が判断する場合、特性要因図の主な用途はどれか。","options":{"A":"原因候補を体系的に整理する","B":"頻度順に並べる","C":"時系列の管理限界を見る","D":"テストケースを生成する"},"answer":"A","explanation":"結果と原因候補を魚の骨状に整理する。"},{"id":"E06Q34","exam":6,"number":34,"category":"品質管理","question":"品質保証担当者が判断する場合、散布図の主な用途はどれか。","options":{"A":"原因候補を階層化する","B":"頻度順に並べる","C":"構成品目を管理する","D":"二つの変数の関係を観察する"},"answer":"D","explanation":"二変数間の関係を見る。"},{"id":"E06Q35","exam":6,"number":35,"category":"品質管理","question":"品質保証担当者が判断する場合、管理図の主な用途はどれか。","options":{"A":"コードを自動生成する","B":"レビュー役割を定義する","C":"プロセスの変動が統計的に安定しているか監視する","D":"機能要求を整理する"},"answer":"C","explanation":"管理限界などを用いて工程の安定性を見る。"},{"id":"E06Q36","exam":6,"number":36,"category":"品質コスト","question":"品質保証担当者が判断する場合、品質教育や標準化活動に要する費用はどれか。","options":{"A":"外部失敗コスト","B":"予防コスト","C":"評価コスト","D":"内部失敗コスト"},"answer":"B","explanation":"不良を未然に防ぐ活動＝予防コスト。"},{"id":"E06Q37","exam":6,"number":37,"category":"品質コスト","question":"品質保証担当者が判断する場合、出荷前の検査・テストに要する費用はどれか。","options":{"A":"予防コスト","B":"評価コスト","C":"内部失敗コスト","D":"外部失敗コスト"},"answer":"B","explanation":"適合性を評価する活動＝評価コスト。"},{"id":"E06Q38","exam":6,"number":38,"category":"品質コスト","question":"品質保証担当者が判断する場合、出荷前に発見された欠陥の修正費用はどれか。","options":{"A":"評価コスト","B":"内部失敗コスト","C":"外部失敗コスト","D":"予防コスト"},"answer":"B","explanation":"顧客へ渡る前の失敗＝内部失敗コスト。"},{"id":"E06Q39","exam":6,"number":39,"category":"品質コスト","question":"品質保証担当者が判断する場合、市場で発生した障害・クレームへの対応費用はどれか。","options":{"A":"内部失敗コスト","B":"外部失敗コスト","C":"予防コスト","D":"評価コスト"},"answer":"B","explanation":"顧客へ渡った後の失敗＝外部失敗コスト。"},{"id":"E06Q40","exam":6,"number":40,"category":"メトリクス","question":"品質保証担当者が判断する場合、gQMの正しい展開順序はどれか。","options":{"A":"Goal→Query→Model","B":"Goal→Quality→Metric","C":"Goal→Question→Metric","D":"Graph→Question→Measure"},"answer":"C","explanation":"GQM = Goal, Question, Metric。 ---"},{"id":"E07Q01","exam":7,"number":1,"category":"メトリクス","question":"品質保証担当者が判断する場合、欠陥密度の例として最も適切なものはどれか。","options":{"A":"KLOC当たりの欠陥数","B":"1日当たり勤務時間","C":"CPU使用率","D":"平均給与"},"answer":"A","explanation":"規模当たり欠陥数が代表例。"},{"id":"E07Q02","exam":7,"number":2,"category":"信頼性指標","question":"品質保証担当者が判断する場合、mTBFが表すものはどれか。","options":{"A":"平均故障間隔","B":"平均応答時間","C":"平均テスト時間","D":"平均修復時間"},"answer":"A","explanation":"MTBF = Mean Time Between Failures。"},{"id":"E07Q03","exam":7,"number":3,"category":"信頼性指標","question":"品質保証担当者が判断する場合、mTTRが一般に表すものはどれか。","options":{"A":"平均レビュー時間","B":"平均要求数","C":"平均修復時間","D":"平均故障間隔"},"answer":"C","explanation":"MTTR = Mean Time To Repair/Recovery。"},{"id":"E07Q04","exam":7,"number":4,"category":"統計","question":"1つの目的変数を複数の説明変数から説明・予測する代表的手法はどれか。","options":{"A":"パレート分析","B":"重回帰分析","C":"クラスター分析","D":"因子分析"},"answer":"B","explanation":"複数説明変数→1目的変数＝重回帰分析。"},{"id":"E07Q05","exam":7,"number":5,"category":"統計","question":"品質保証担当者が判断する場合、似た特徴を持つ対象をグループ化する手法はどれか。","options":{"A":"重回帰分析","B":"クラスター分析","C":"因子分析","D":"管理図"},"answer":"B","explanation":"類似対象のグループ化＝クラスター分析。"},{"id":"E07Q06","exam":7,"number":6,"category":"統計","question":"品質保証担当者が判断する場合、観測変数の背後にある潜在的な因子を探る手法はどれか。","options":{"A":"クラスター分析","B":"因子分析","C":"散布図","D":"重回帰分析"},"answer":"B","explanation":"潜在因子の探索＝因子分析。"},{"id":"E07Q07","exam":7,"number":7,"category":"構成管理","question":"品質保証担当者が判断する場合、ベースラインの説明として適切なのはどれか。","options":{"A":"個人PCの一時保存","B":"バックアップだけを指す","C":"正式に合意され変更管理の対象となる基準状態","D":"最新ファイルなら何でもよい"},"answer":"C","explanation":"ベースライン変更は正式な変更管理下で行う。"},{"id":"E07Q08","exam":7,"number":8,"category":"構成管理","question":"品質保証担当者が判断する場合、構成管理で不適切な行為はどれか。","options":{"A":"リリース対象を管理する","B":"構成品目を識別する","C":"変更履歴を記録する","D":"担当者個人が無手続でベースライン変更を確定する"},"answer":"D","explanation":"ベースライン変更は権限ある仕組みで統制する。"},{"id":"E07Q09","exam":7,"number":9,"category":"品質計画","question":"品質保証担当者が判断する場合、品質計画について最も適切なものはどれか。","options":{"A":"一度作れば固定する","B":"要求やプロセス変更に応じて見直す","C":"合否基準を含めない","D":"品質評価計画を含めない"},"answer":"B","explanation":"品質計画は状況変化に応じて更新する。"},{"id":"E07Q10","exam":7,"number":10,"category":"改善","question":"品質保証担当者が判断する場合、根本原因分析の目的として最も適切なものはどれか。","options":{"A":"根本原因を特定し再発防止につなげる","B":"障害を一時回避するだけ","C":"欠陥件数を減らして記録する","D":"責任者を処罰する"},"answer":"A","explanation":"原因の深掘りと再発防止が目的。"},{"id":"E07Q11","exam":7,"number":11,"category":"改善","question":"品質保証担当者が判断する場合、pDCAの正しい順序はどれか。","options":{"A":"Do→Plan→Act→Check","B":"Plan→Act→Do→Check","C":"Plan→Check→Do→Act","D":"Plan→Do→Check→Act"},"answer":"D","explanation":"Plan, Do, Check, Act。"},{"id":"E07Q12","exam":7,"number":12,"category":"リスク","question":"品質保証担当者が判断する場合、リスクベースドテストの考え方として適切なのはどれか。","options":{"A":"担当者の好みだけで決める","B":"全機能へ同量のテストを割り当てる","C":"発生可能性や影響度を考慮して優先度を決める","D":"テストを行わずリスク評価だけする"},"answer":"C","explanation":"高リスク領域へ重点的にテスト資源を配分する。"},{"id":"E07Q13","exam":7,"number":13,"category":"CI/CD","question":"品質保証担当者が判断する場合、cIの説明として最も適切なものはどれか。","options":{"A":"変更を頻繁に統合しビルドやテスト等を自動化する","B":"本番デプロイだけを指す","C":"統合を手作業中心にする","D":"自動化後は結果確認不要"},"answer":"A","explanation":"CIは継続的統合。自動化しても結果確認は必要。"},{"id":"E07Q14","exam":7,"number":14,"category":"ITサービス","question":"品質保証担当者が判断する場合、iTILが主に扱うものはどれか。","options":{"A":"ソースコード生成","B":"統計解析だけ","C":"UI設計だけ","D":"ITサービスマネジメント"},"answer":"D","explanation":"ITILはITサービスマネジメントのベストプラクティス。"},{"id":"E07Q15","exam":7,"number":15,"category":"セーフティ","question":"品質保証担当者が判断する場合、ハザードの説明として適切なのはどれか。","options":{"A":"品質目標","B":"構成品目","C":"危害を引き起こす潜在的な原因","D":"実際に生じた損害そのもの"},"answer":"C","explanation":"ハザード＝危害につながる潜在的原因。"},{"id":"E07Q16","exam":7,"number":16,"category":"セーフティ","question":"品質保証担当者が判断する場合、本質安全の考え方として最も近いものはどれか。","options":{"A":"ログを残すだけ","B":"ハザードそのものを除去・低減する","C":"ハザード発生後だけ警告する","D":"バックアップを取るだけ"},"answer":"B","explanation":"危険源そのものを抑える＝本質安全。"},{"id":"E07Q17","exam":7,"number":17,"category":"セーフティ","question":"品質保証担当者が判断する場合、機能安全の考え方として最も近いものはどれか。","options":{"A":"安全関連機能によって危害へ至るリスクを低減する","B":"危険源を物理的に必ずゼロにする","C":"可用性だけを高める","D":"暗号化だけを行う"},"answer":"A","explanation":"安全機能によってリスクを許容可能にする。"},{"id":"E07Q18","exam":7,"number":18,"category":"AI品質","question":"品質保証担当者が判断する場合、aIシステムの品質評価で適切なものはどれか。","options":{"A":"通常ソフトと完全に同じ観点だけで十分","B":"精度だけ見ればよい","C":"テストは不要","D":"学習データやモデル特性も含めて評価する"},"answer":"D","explanation":"データ・モデル特有の品質も考慮する。"},{"id":"E07Q19","exam":7,"number":19,"category":"IoT品質","question":"品質保証担当者が判断する場合、ioTシステムの品質で適切な考え方はどれか。","options":{"A":"ローカルPCだけを見る","B":"品質管理は不要","C":"デバイス・通信・クラウド等を含む全体を考慮する","D":"アプリ画面だけを見る"},"answer":"C","explanation":"複数要素からなるシステム全体で品質を捉える。"},{"id":"E07Q20","exam":7,"number":20,"category":"クラウド品質","question":"品質保証担当者が判断する場合、クラウド利用時の品質で考慮すべきものはどれか。","options":{"A":"性能は常に一定","B":"可用性・セキュリティ・サービス依存性など","C":"障害は起きないので品質活動不要","D":"テスト不要"},"answer":"B","explanation":"クラウド固有の依存関係や運用品質も考慮する。"},{"id":"E07Q21","exam":7,"number":21,"category":"品質概念","question":"新規プロジェクトで、verificationの説明として最も適切なものはどれか。","options":{"A":"成果物が規定要求どおり正しく作られているか確認する","B":"運用コストだけを確認する","C":"市場シェアを確認する","D":"利用者のニーズに合う製品かを確認する"},"answer":"A","explanation":"Verificationは「正しく作っているか」を確認する。Validationは「正しいものを作っているか」。"},{"id":"E07Q22","exam":7,"number":22,"category":"品質概念","question":"新規プロジェクトで、validationの説明として最も適切なものはどれか。","options":{"A":"構成品目を識別する","B":"欠陥密度を測る","C":"成果物が上位仕様に適合しているかだけを見る","D":"利用者の意図した用途・ニーズを満たすか確認する"},"answer":"D","explanation":"Validationは意図した用途や利用者ニーズを満たすかを確認する。"},{"id":"E07Q23","exam":7,"number":23,"category":"品質モデル","question":"新規プロジェクトで、通常運用時に信頼性要求を満たして安定して動作する性質はどれか。","options":{"A":"回復性","B":"成熟性","C":"可用性","D":"障害許容性"},"answer":"B","explanation":"平常時＝成熟性。"},{"id":"E07Q24","exam":7,"number":24,"category":"品質モデル","question":"新規プロジェクトで、障害発生中でも必要な機能を継続できる性質はどれか。","options":{"A":"成熟性","B":"可用性","C":"障害許容性","D":"回復性"},"answer":"C","explanation":"障害中＝障害許容性。"},{"id":"E07Q25","exam":7,"number":25,"category":"品質モデル","question":"新規プロジェクトで、障害後にデータや状態を復旧できる性質はどれか。","options":{"A":"可用性","B":"障害許容性","C":"回復性","D":"成熟性"},"answer":"C","explanation":"障害後＝回復性。"},{"id":"E07Q26","exam":7,"number":26,"category":"品質モデル","question":"新規プロジェクトで、必要な時にシステムを利用できる性質はどれか。","options":{"A":"障害許容性","B":"回復性","C":"成熟性","D":"可用性"},"answer":"D","explanation":"利用可能である度合い＝可用性。"},{"id":"E07Q27","exam":7,"number":27,"category":"保守性","question":"新規プロジェクトで、あるモジュールの変更が他モジュールへ波及しにくい性質はどれか。","options":{"A":"試験性","B":"解析性","C":"モジュール性","D":"修正性"},"answer":"C","explanation":"変更影響の局所化＝モジュール性。"},{"id":"E07Q28","exam":7,"number":28,"category":"保守性","question":"新規プロジェクトで、障害原因や変更対象を調査しやすい性質はどれか。","options":{"A":"解析性","B":"再利用性","C":"修正性","D":"試験性"},"answer":"A","explanation":"原因・変更箇所を分析しやすい＝解析性。"},{"id":"E07Q29","exam":7,"number":29,"category":"保守性","question":"新規プロジェクトで、変更後のソフトウェアを効率よくテストできる性質はどれか。","options":{"A":"再利用性","B":"修正性","C":"試験性","D":"解析性"},"answer":"C","explanation":"テストしやすさ＝試験性。"},{"id":"E07Q30","exam":7,"number":30,"category":"セキュリティ","question":"新規プロジェクトで、許可されていない者による情報閲覧を防ぐ性質はどれか。","options":{"A":"真正性","B":"責任追跡性","C":"機密性","D":"インテグリティ"},"answer":"C","explanation":"見せない＝機密性。"},{"id":"E07Q31","exam":7,"number":31,"category":"セキュリティ","question":"新規プロジェクトで、権限のない変更・改ざんを防ぐ性質はどれか。","options":{"A":"否認防止性","B":"機密性","C":"インテグリティ","D":"真正性"},"answer":"C","explanation":"変えさせない＝インテグリティ。"},{"id":"E07Q32","exam":7,"number":32,"category":"セキュリティ","question":"新規プロジェクトで、操作を行った主体を後から追跡できる性質はどれか。","options":{"A":"真正性","B":"責任追跡性","C":"否認防止性","D":"機密性"},"answer":"B","explanation":"誰が行ったか追える＝責任追跡性。"},{"id":"E07Q33","exam":7,"number":33,"category":"セキュリティ","question":"新規プロジェクトで、利用者が主張どおりの本人であることを確認する性質はどれか。","options":{"A":"責任追跡性","B":"否認防止性","C":"インテグリティ","D":"真正性"},"answer":"D","explanation":"本当に本人か＝真正性。"},{"id":"E07Q34","exam":7,"number":34,"category":"セキュリティ","question":"新規プロジェクトで、電子的な操作を後から『自分はしていない』と否定できないようにする性質はどれか。","options":{"A":"否認防止性","B":"機密性","C":"真正性","D":"責任追跡性"},"answer":"A","explanation":"行為の否定を防ぐ＝否認防止性。"},{"id":"E07Q35","exam":7,"number":35,"category":"レビュー","question":"新規プロジェクトで、インスペクションの特徴として最も適切なものはどれか。","options":{"A":"テスト完了後だけ行う","B":"作成者だけで自由に確認する","C":"役割や手順を定め体系的に行う","D":"必ずプログラムを実行する"},"answer":"C","explanation":"インスペクションは比較的形式的なレビュー。"},{"id":"E07Q36","exam":7,"number":36,"category":"レビュー","question":"新規プロジェクトで、ウォークスルーの特徴として最も適切なものはどれか。","options":{"A":"作成者が説明を主導することが多い","B":"必ず監査部門が主導する","C":"動的テストの一種である","D":"構成管理の一種である"},"answer":"A","explanation":"ウォークスルーは作成者主導で説明・確認する形が代表的。"},{"id":"E07Q37","exam":7,"number":37,"category":"テスト","question":"新規プロジェクトで、同値分割法の説明として最も適切なものはどれか。","options":{"A":"境界値だけを試す","B":"内部分岐をすべて実行する","C":"無作為値だけを使う","D":"同様の振る舞いが期待される入力集合に分割する"},"answer":"D","explanation":"同値クラスごとに代表値を選ぶ。"},{"id":"E07Q38","exam":7,"number":38,"category":"テスト","question":"入力範囲が1以上100以下のとき、境界値分析で特に有効な組合せはどれか。","options":{"A":"0,1,100,101","B":"10,20,30,40","C":"25,50,75","D":"1,100"},"answer":"A","explanation":"境界の直前・境界・直後を重視する。"},{"id":"E07Q39","exam":7,"number":39,"category":"テスト","question":"新規プロジェクトで、複数条件の組合せと結果の関係を整理してテストする技法はどれか。","options":{"A":"探索的テスト","B":"状態遷移テスト","C":"デシジョンテーブルテスト","D":"命令網羅"},"answer":"C","explanation":"条件組合せ＝デシジョンテーブル。"},{"id":"E07Q40","exam":7,"number":40,"category":"テスト","question":"新規プロジェクトで、状態によって同じイベントへの応答が変化するシステムに適した技法はどれか。","options":{"A":"状態遷移テスト","B":"同値分割","C":"分岐網羅","D":"静的解析"},"answer":"A","explanation":"状態と遷移を持つ対象には状態遷移テスト。 ---"},{"id":"E08Q01","exam":8,"number":1,"category":"テスト","question":"新規プロジェクトで、変更による既存機能への悪影響を確認するテストはどれか。","options":{"A":"回帰テスト","B":"負荷テスト","C":"ユーザビリティテスト","D":"受入テスト"},"answer":"A","explanation":"変更後の副作用確認＝回帰テスト。"},{"id":"E08Q02","exam":8,"number":2,"category":"テスト","question":"新規プロジェクトで、内部の制御構造を基に網羅率を測るテストはどれか。","options":{"A":"受入テスト","B":"ユーザビリティテスト","C":"ブラックボックステスト","D":"ホワイトボックステスト"},"answer":"D","explanation":"命令・分岐など内部構造に着目＝ホワイトボックス。"},{"id":"E08Q03","exam":8,"number":3,"category":"テスト","question":"新規プロジェクトで、テストで欠陥が見つからなかった場合の判断として適切なのはどれか。","options":{"A":"テストは不要だった","B":"欠陥が存在しないことが証明された","C":"品質100%である","D":"実施したテストでは発見されなかっただけである"},"answer":"D","explanation":"テストは欠陥の不在を完全には証明できない。"},{"id":"E08Q04","exam":8,"number":4,"category":"品質管理","question":"新規プロジェクトで、パレート図の主な用途はどれか。","options":{"A":"時系列変化を監視する","B":"重要な問題を優先順位付けする","C":"二変数の相関を見る","D":"原因候補を枝状に整理する"},"answer":"B","explanation":"大きい項目から並べ重点問題を把握する。"},{"id":"E08Q05","exam":8,"number":5,"category":"品質管理","question":"新規プロジェクトで、特性要因図の主な用途はどれか。","options":{"A":"頻度順に並べる","B":"時系列の管理限界を見る","C":"テストケースを生成する","D":"原因候補を体系的に整理する"},"answer":"D","explanation":"結果と原因候補を魚の骨状に整理する。"},{"id":"E08Q06","exam":8,"number":6,"category":"品質管理","question":"新規プロジェクトで、散布図の主な用途はどれか。","options":{"A":"頻度順に並べる","B":"構成品目を管理する","C":"二つの変数の関係を観察する","D":"原因候補を階層化する"},"answer":"C","explanation":"二変数間の関係を見る。"},{"id":"E08Q07","exam":8,"number":7,"category":"品質管理","question":"新規プロジェクトで、管理図の主な用途はどれか。","options":{"A":"レビュー役割を定義する","B":"プロセスの変動が統計的に安定しているか監視する","C":"機能要求を整理する","D":"コードを自動生成する"},"answer":"B","explanation":"管理限界などを用いて工程の安定性を見る。"},{"id":"E08Q08","exam":8,"number":8,"category":"品質コスト","question":"新規プロジェクトで、品質教育や標準化活動に要する費用はどれか。","options":{"A":"予防コスト","B":"評価コスト","C":"内部失敗コスト","D":"外部失敗コスト"},"answer":"A","explanation":"不良を未然に防ぐ活動＝予防コスト。"},{"id":"E08Q09","exam":8,"number":9,"category":"品質コスト","question":"新規プロジェクトで、出荷前の検査・テストに要する費用はどれか。","options":{"A":"評価コスト","B":"内部失敗コスト","C":"外部失敗コスト","D":"予防コスト"},"answer":"A","explanation":"適合性を評価する活動＝評価コスト。"},{"id":"E08Q10","exam":8,"number":10,"category":"品質コスト","question":"新規プロジェクトで、出荷前に発見された欠陥の修正費用はどれか。","options":{"A":"内部失敗コスト","B":"外部失敗コスト","C":"予防コスト","D":"評価コスト"},"answer":"A","explanation":"顧客へ渡る前の失敗＝内部失敗コスト。"},{"id":"E08Q11","exam":8,"number":11,"category":"品質コスト","question":"新規プロジェクトで、市場で発生した障害・クレームへの対応費用はどれか。","options":{"A":"外部失敗コスト","B":"予防コスト","C":"評価コスト","D":"内部失敗コスト"},"answer":"A","explanation":"顧客へ渡った後の失敗＝外部失敗コスト。"},{"id":"E08Q12","exam":8,"number":12,"category":"メトリクス","question":"新規プロジェクトで、gQMの正しい展開順序はどれか。","options":{"A":"Goal→Quality→Metric","B":"Goal→Question→Metric","C":"Graph→Question→Measure","D":"Goal→Query→Model"},"answer":"B","explanation":"GQM = Goal, Question, Metric。"},{"id":"E08Q13","exam":8,"number":13,"category":"メトリクス","question":"新規プロジェクトで、欠陥密度の例として最も適切なものはどれか。","options":{"A":"1日当たり勤務時間","B":"CPU使用率","C":"平均給与","D":"KLOC当たりの欠陥数"},"answer":"D","explanation":"規模当たり欠陥数が代表例。"},{"id":"E08Q14","exam":8,"number":14,"category":"信頼性指標","question":"新規プロジェクトで、mTBFが表すものはどれか。","options":{"A":"平均応答時間","B":"平均テスト時間","C":"平均修復時間","D":"平均故障間隔"},"answer":"D","explanation":"MTBF = Mean Time Between Failures。"},{"id":"E08Q15","exam":8,"number":15,"category":"信頼性指標","question":"新規プロジェクトで、mTTRが一般に表すものはどれか。","options":{"A":"平均要求数","B":"平均修復時間","C":"平均故障間隔","D":"平均レビュー時間"},"answer":"B","explanation":"MTTR = Mean Time To Repair/Recovery。"},{"id":"E08Q16","exam":8,"number":16,"category":"統計","question":"1つの目的変数を複数の説明変数から説明・予測する代表的手法はどれか。","options":{"A":"重回帰分析","B":"クラスター分析","C":"因子分析","D":"パレート分析"},"answer":"A","explanation":"複数説明変数→1目的変数＝重回帰分析。"},{"id":"E08Q17","exam":8,"number":17,"category":"統計","question":"新規プロジェクトで、似た特徴を持つ対象をグループ化する手法はどれか。","options":{"A":"クラスター分析","B":"因子分析","C":"管理図","D":"重回帰分析"},"answer":"A","explanation":"類似対象のグループ化＝クラスター分析。"},{"id":"E08Q18","exam":8,"number":18,"category":"統計","question":"新規プロジェクトで、観測変数の背後にある潜在的な因子を探る手法はどれか。","options":{"A":"因子分析","B":"散布図","C":"重回帰分析","D":"クラスター分析"},"answer":"A","explanation":"潜在因子の探索＝因子分析。"},{"id":"E08Q19","exam":8,"number":19,"category":"構成管理","question":"新規プロジェクトで、ベースラインの説明として適切なのはどれか。","options":{"A":"バックアップだけを指す","B":"正式に合意され変更管理の対象となる基準状態","C":"最新ファイルなら何でもよい","D":"個人PCの一時保存"},"answer":"B","explanation":"ベースライン変更は正式な変更管理下で行う。"},{"id":"E08Q20","exam":8,"number":20,"category":"構成管理","question":"新規プロジェクトで、構成管理で不適切な行為はどれか。","options":{"A":"構成品目を識別する","B":"変更履歴を記録する","C":"担当者個人が無手続でベースライン変更を確定する","D":"リリース対象を管理する"},"answer":"C","explanation":"ベースライン変更は権限ある仕組みで統制する。"},{"id":"E08Q21","exam":8,"number":21,"category":"品質計画","question":"新規プロジェクトで、品質計画について最も適切なものはどれか。","options":{"A":"要求やプロセス変更に応じて見直す","B":"合否基準を含めない","C":"品質評価計画を含めない","D":"一度作れば固定する"},"answer":"A","explanation":"品質計画は状況変化に応じて更新する。"},{"id":"E08Q22","exam":8,"number":22,"category":"改善","question":"新規プロジェクトで、根本原因分析の目的として最も適切なものはどれか。","options":{"A":"障害を一時回避するだけ","B":"欠陥件数を減らして記録する","C":"責任者を処罰する","D":"根本原因を特定し再発防止につなげる"},"answer":"D","explanation":"原因の深掘りと再発防止が目的。"},{"id":"E08Q23","exam":8,"number":23,"category":"改善","question":"新規プロジェクトで、pDCAの正しい順序はどれか。","options":{"A":"Plan→Act→Do→Check","B":"Plan→Check→Do→Act","C":"Plan→Do→Check→Act","D":"Do→Plan→Act→Check"},"answer":"C","explanation":"Plan, Do, Check, Act。"},{"id":"E08Q24","exam":8,"number":24,"category":"リスク","question":"新規プロジェクトで、リスクベースドテストの考え方として適切なのはどれか。","options":{"A":"全機能へ同量のテストを割り当てる","B":"発生可能性や影響度を考慮して優先度を決める","C":"テストを行わずリスク評価だけする","D":"担当者の好みだけで決める"},"answer":"B","explanation":"高リスク領域へ重点的にテスト資源を配分する。"},{"id":"E08Q25","exam":8,"number":25,"category":"CI/CD","question":"新規プロジェクトで、cIの説明として最も適切なものはどれか。","options":{"A":"本番デプロイだけを指す","B":"統合を手作業中心にする","C":"自動化後は結果確認不要","D":"変更を頻繁に統合しビルドやテスト等を自動化する"},"answer":"D","explanation":"CIは継続的統合。自動化しても結果確認は必要。"},{"id":"E08Q26","exam":8,"number":26,"category":"ITサービス","question":"新規プロジェクトで、iTILが主に扱うものはどれか。","options":{"A":"統計解析だけ","B":"UI設計だけ","C":"ITサービスマネジメント","D":"ソースコード生成"},"answer":"C","explanation":"ITILはITサービスマネジメントのベストプラクティス。"},{"id":"E08Q27","exam":8,"number":27,"category":"セーフティ","question":"新規プロジェクトで、ハザードの説明として適切なのはどれか。","options":{"A":"構成品目","B":"危害を引き起こす潜在的な原因","C":"実際に生じた損害そのもの","D":"品質目標"},"answer":"B","explanation":"ハザード＝危害につながる潜在的原因。"},{"id":"E08Q28","exam":8,"number":28,"category":"セーフティ","question":"新規プロジェクトで、本質安全の考え方として最も近いものはどれか。","options":{"A":"ハザードそのものを除去・低減する","B":"ハザード発生後だけ警告する","C":"バックアップを取るだけ","D":"ログを残すだけ"},"answer":"A","explanation":"危険源そのものを抑える＝本質安全。"},{"id":"E08Q29","exam":8,"number":29,"category":"セーフティ","question":"新規プロジェクトで、機能安全の考え方として最も近いものはどれか。","options":{"A":"危険源を物理的に必ずゼロにする","B":"可用性だけを高める","C":"暗号化だけを行う","D":"安全関連機能によって危害へ至るリスクを低減する"},"answer":"D","explanation":"安全機能によってリスクを許容可能にする。"},{"id":"E08Q30","exam":8,"number":30,"category":"AI品質","question":"新規プロジェクトで、aIシステムの品質評価で適切なものはどれか。","options":{"A":"精度だけ見ればよい","B":"テストは不要","C":"学習データやモデル特性も含めて評価する","D":"通常ソフトと完全に同じ観点だけで十分"},"answer":"C","explanation":"データ・モデル特有の品質も考慮する。"},{"id":"E08Q31","exam":8,"number":31,"category":"IoT品質","question":"新規プロジェクトで、ioTシステムの品質で適切な考え方はどれか。","options":{"A":"品質管理は不要","B":"デバイス・通信・クラウド等を含む全体を考慮する","C":"アプリ画面だけを見る","D":"ローカルPCだけを見る"},"answer":"B","explanation":"複数要素からなるシステム全体で品質を捉える。"},{"id":"E08Q32","exam":8,"number":32,"category":"クラウド品質","question":"新規プロジェクトで、クラウド利用時の品質で考慮すべきものはどれか。","options":{"A":"可用性・セキュリティ・サービス依存性など","B":"障害は起きないので品質活動不要","C":"テスト不要","D":"性能は常に一定"},"answer":"A","explanation":"クラウド固有の依存関係や運用品質も考慮する。"},{"id":"E08Q33","exam":8,"number":33,"category":"品質概念","question":"保守フェーズにおいて、verificationの説明として最も適切なものはどれか。","options":{"A":"運用コストだけを確認する","B":"市場シェアを確認する","C":"利用者のニーズに合う製品かを確認する","D":"成果物が規定要求どおり正しく作られているか確認する"},"answer":"D","explanation":"Verificationは「正しく作っているか」を確認する。Validationは「正しいものを作っているか」。"},{"id":"E08Q34","exam":8,"number":34,"category":"品質概念","question":"保守フェーズにおいて、validationの説明として最も適切なものはどれか。","options":{"A":"欠陥密度を測る","B":"成果物が上位仕様に適合しているかだけを見る","C":"利用者の意図した用途・ニーズを満たすか確認する","D":"構成品目を識別する"},"answer":"C","explanation":"Validationは意図した用途や利用者ニーズを満たすかを確認する。"},{"id":"E08Q35","exam":8,"number":35,"category":"品質モデル","question":"保守フェーズにおいて、通常運用時に信頼性要求を満たして安定して動作する性質はどれか。","options":{"A":"成熟性","B":"可用性","C":"障害許容性","D":"回復性"},"answer":"A","explanation":"平常時＝成熟性。"},{"id":"E08Q36","exam":8,"number":36,"category":"品質モデル","question":"保守フェーズにおいて、障害発生中でも必要な機能を継続できる性質はどれか。","options":{"A":"可用性","B":"障害許容性","C":"回復性","D":"成熟性"},"answer":"B","explanation":"障害中＝障害許容性。"},{"id":"E08Q37","exam":8,"number":37,"category":"品質モデル","question":"保守フェーズにおいて、障害後にデータや状態を復旧できる性質はどれか。","options":{"A":"障害許容性","B":"回復性","C":"成熟性","D":"可用性"},"answer":"B","explanation":"障害後＝回復性。"},{"id":"E08Q38","exam":8,"number":38,"category":"品質モデル","question":"保守フェーズにおいて、必要な時にシステムを利用できる性質はどれか。","options":{"A":"回復性","B":"成熟性","C":"可用性","D":"障害許容性"},"answer":"C","explanation":"利用可能である度合い＝可用性。"},{"id":"E08Q39","exam":8,"number":39,"category":"保守性","question":"保守フェーズにおいて、あるモジュールの変更が他モジュールへ波及しにくい性質はどれか。","options":{"A":"解析性","B":"モジュール性","C":"修正性","D":"試験性"},"answer":"B","explanation":"変更影響の局所化＝モジュール性。"},{"id":"E08Q40","exam":8,"number":40,"category":"保守性","question":"保守フェーズにおいて、障害原因や変更対象を調査しやすい性質はどれか。","options":{"A":"再利用性","B":"修正性","C":"試験性","D":"解析性"},"answer":"D","explanation":"原因・変更箇所を分析しやすい＝解析性。 ---"},{"id":"E09Q01","exam":9,"number":1,"category":"保守性","question":"保守フェーズにおいて、変更後のソフトウェアを効率よくテストできる性質はどれか。","options":{"A":"修正性","B":"試験性","C":"解析性","D":"再利用性"},"answer":"B","explanation":"テストしやすさ＝試験性。"},{"id":"E09Q02","exam":9,"number":2,"category":"セキュリティ","question":"保守フェーズにおいて、許可されていない者による情報閲覧を防ぐ性質はどれか。","options":{"A":"責任追跡性","B":"機密性","C":"インテグリティ","D":"真正性"},"answer":"B","explanation":"見せない＝機密性。"},{"id":"E09Q03","exam":9,"number":3,"category":"セキュリティ","question":"保守フェーズにおいて、権限のない変更・改ざんを防ぐ性質はどれか。","options":{"A":"機密性","B":"インテグリティ","C":"真正性","D":"否認防止性"},"answer":"B","explanation":"変えさせない＝インテグリティ。"},{"id":"E09Q04","exam":9,"number":4,"category":"セキュリティ","question":"保守フェーズにおいて、操作を行った主体を後から追跡できる性質はどれか。","options":{"A":"責任追跡性","B":"否認防止性","C":"機密性","D":"真正性"},"answer":"A","explanation":"誰が行ったか追える＝責任追跡性。"},{"id":"E09Q05","exam":9,"number":5,"category":"セキュリティ","question":"保守フェーズにおいて、利用者が主張どおりの本人であることを確認する性質はどれか。","options":{"A":"否認防止性","B":"インテグリティ","C":"真正性","D":"責任追跡性"},"answer":"C","explanation":"本当に本人か＝真正性。"},{"id":"E09Q06","exam":9,"number":6,"category":"セキュリティ","question":"保守フェーズにおいて、電子的な操作を後から『自分はしていない』と否定できないようにする性質はどれか。","options":{"A":"機密性","B":"真正性","C":"責任追跡性","D":"否認防止性"},"answer":"D","explanation":"行為の否定を防ぐ＝否認防止性。"},{"id":"E09Q07","exam":9,"number":7,"category":"レビュー","question":"保守フェーズにおいて、インスペクションの特徴として最も適切なものはどれか。","options":{"A":"作成者だけで自由に確認する","B":"役割や手順を定め体系的に行う","C":"必ずプログラムを実行する","D":"テスト完了後だけ行う"},"answer":"B","explanation":"インスペクションは比較的形式的なレビュー。"},{"id":"E09Q08","exam":9,"number":8,"category":"レビュー","question":"保守フェーズにおいて、ウォークスルーの特徴として最も適切なものはどれか。","options":{"A":"必ず監査部門が主導する","B":"動的テストの一種である","C":"構成管理の一種である","D":"作成者が説明を主導することが多い"},"answer":"D","explanation":"ウォークスルーは作成者主導で説明・確認する形が代表的。"},{"id":"E09Q09","exam":9,"number":9,"category":"テスト","question":"保守フェーズにおいて、同値分割法の説明として最も適切なものはどれか。","options":{"A":"内部分岐をすべて実行する","B":"無作為値だけを使う","C":"同様の振る舞いが期待される入力集合に分割する","D":"境界値だけを試す"},"answer":"C","explanation":"同値クラスごとに代表値を選ぶ。"},{"id":"E09Q10","exam":9,"number":10,"category":"テスト","question":"入力範囲が1以上100以下のとき、境界値分析で特に有効な組合せはどれか。","options":{"A":"10,20,30,40","B":"25,50,75","C":"1,100","D":"0,1,100,101"},"answer":"D","explanation":"境界の直前・境界・直後を重視する。"},{"id":"E09Q11","exam":9,"number":11,"category":"テスト","question":"保守フェーズにおいて、複数条件の組合せと結果の関係を整理してテストする技法はどれか。","options":{"A":"状態遷移テスト","B":"デシジョンテーブルテスト","C":"命令網羅","D":"探索的テスト"},"answer":"B","explanation":"条件組合せ＝デシジョンテーブル。"},{"id":"E09Q12","exam":9,"number":12,"category":"テスト","question":"保守フェーズにおいて、状態によって同じイベントへの応答が変化するシステムに適した技法はどれか。","options":{"A":"同値分割","B":"分岐網羅","C":"静的解析","D":"状態遷移テスト"},"answer":"D","explanation":"状態と遷移を持つ対象には状態遷移テスト。"},{"id":"E09Q13","exam":9,"number":13,"category":"テスト","question":"保守フェーズにおいて、変更による既存機能への悪影響を確認するテストはどれか。","options":{"A":"負荷テスト","B":"ユーザビリティテスト","C":"受入テスト","D":"回帰テスト"},"answer":"D","explanation":"変更後の副作用確認＝回帰テスト。"},{"id":"E09Q14","exam":9,"number":14,"category":"テスト","question":"保守フェーズにおいて、内部の制御構造を基に網羅率を測るテストはどれか。","options":{"A":"ユーザビリティテスト","B":"ブラックボックステスト","C":"ホワイトボックステスト","D":"受入テスト"},"answer":"C","explanation":"命令・分岐など内部構造に着目＝ホワイトボックス。"},{"id":"E09Q15","exam":9,"number":15,"category":"テスト","question":"保守フェーズにおいて、テストで欠陥が見つからなかった場合の判断として適切なのはどれか。","options":{"A":"欠陥が存在しないことが証明された","B":"品質100%である","C":"実施したテストでは発見されなかっただけである","D":"テストは不要だった"},"answer":"C","explanation":"テストは欠陥の不在を完全には証明できない。"},{"id":"E09Q16","exam":9,"number":16,"category":"品質管理","question":"保守フェーズにおいて、パレート図の主な用途はどれか。","options":{"A":"重要な問題を優先順位付けする","B":"二変数の相関を見る","C":"原因候補を枝状に整理する","D":"時系列変化を監視する"},"answer":"A","explanation":"大きい項目から並べ重点問題を把握する。"},{"id":"E09Q17","exam":9,"number":17,"category":"品質管理","question":"保守フェーズにおいて、特性要因図の主な用途はどれか。","options":{"A":"時系列の管理限界を見る","B":"テストケースを生成する","C":"原因候補を体系的に整理する","D":"頻度順に並べる"},"answer":"C","explanation":"結果と原因候補を魚の骨状に整理する。"},{"id":"E09Q18","exam":9,"number":18,"category":"品質管理","question":"保守フェーズにおいて、散布図の主な用途はどれか。","options":{"A":"構成品目を管理する","B":"二つの変数の関係を観察する","C":"原因候補を階層化する","D":"頻度順に並べる"},"answer":"B","explanation":"二変数間の関係を見る。"},{"id":"E09Q19","exam":9,"number":19,"category":"品質管理","question":"保守フェーズにおいて、管理図の主な用途はどれか。","options":{"A":"プロセスの変動が統計的に安定しているか監視する","B":"機能要求を整理する","C":"コードを自動生成する","D":"レビュー役割を定義する"},"answer":"A","explanation":"管理限界などを用いて工程の安定性を見る。"},{"id":"E09Q20","exam":9,"number":20,"category":"品質コスト","question":"保守フェーズにおいて、品質教育や標準化活動に要する費用はどれか。","options":{"A":"評価コスト","B":"内部失敗コスト","C":"外部失敗コスト","D":"予防コスト"},"answer":"D","explanation":"不良を未然に防ぐ活動＝予防コスト。"},{"id":"E09Q21","exam":9,"number":21,"category":"品質コスト","question":"保守フェーズにおいて、出荷前の検査・テストに要する費用はどれか。","options":{"A":"内部失敗コスト","B":"外部失敗コスト","C":"予防コスト","D":"評価コスト"},"answer":"D","explanation":"適合性を評価する活動＝評価コスト。"},{"id":"E09Q22","exam":9,"number":22,"category":"品質コスト","question":"保守フェーズにおいて、出荷前に発見された欠陥の修正費用はどれか。","options":{"A":"外部失敗コスト","B":"予防コスト","C":"評価コスト","D":"内部失敗コスト"},"answer":"D","explanation":"顧客へ渡る前の失敗＝内部失敗コスト。"},{"id":"E09Q23","exam":9,"number":23,"category":"品質コスト","question":"保守フェーズにおいて、市場で発生した障害・クレームへの対応費用はどれか。","options":{"A":"予防コスト","B":"評価コスト","C":"内部失敗コスト","D":"外部失敗コスト"},"answer":"D","explanation":"顧客へ渡った後の失敗＝外部失敗コスト。"},{"id":"E09Q24","exam":9,"number":24,"category":"メトリクス","question":"保守フェーズにおいて、gQMの正しい展開順序はどれか。","options":{"A":"Goal→Question→Metric","B":"Graph→Question→Measure","C":"Goal→Query→Model","D":"Goal→Quality→Metric"},"answer":"A","explanation":"GQM = Goal, Question, Metric。"},{"id":"E09Q25","exam":9,"number":25,"category":"メトリクス","question":"保守フェーズにおいて、欠陥密度の例として最も適切なものはどれか。","options":{"A":"CPU使用率","B":"平均給与","C":"KLOC当たりの欠陥数","D":"1日当たり勤務時間"},"answer":"C","explanation":"規模当たり欠陥数が代表例。"},{"id":"E09Q26","exam":9,"number":26,"category":"信頼性指標","question":"保守フェーズにおいて、mTBFが表すものはどれか。","options":{"A":"平均テスト時間","B":"平均修復時間","C":"平均故障間隔","D":"平均応答時間"},"answer":"C","explanation":"MTBF = Mean Time Between Failures。"},{"id":"E09Q27","exam":9,"number":27,"category":"信頼性指標","question":"保守フェーズにおいて、mTTRが一般に表すものはどれか。","options":{"A":"平均修復時間","B":"平均故障間隔","C":"平均レビュー時間","D":"平均要求数"},"answer":"A","explanation":"MTTR = Mean Time To Repair/Recovery。"},{"id":"E09Q28","exam":9,"number":28,"category":"統計","question":"1つの目的変数を複数の説明変数から説明・予測する代表的手法はどれか。","options":{"A":"クラスター分析","B":"因子分析","C":"パレート分析","D":"重回帰分析"},"answer":"D","explanation":"複数説明変数→1目的変数＝重回帰分析。"},{"id":"E09Q29","exam":9,"number":29,"category":"統計","question":"保守フェーズにおいて、似た特徴を持つ対象をグループ化する手法はどれか。","options":{"A":"因子分析","B":"管理図","C":"重回帰分析","D":"クラスター分析"},"answer":"D","explanation":"類似対象のグループ化＝クラスター分析。"},{"id":"E09Q30","exam":9,"number":30,"category":"統計","question":"保守フェーズにおいて、観測変数の背後にある潜在的な因子を探る手法はどれか。","options":{"A":"散布図","B":"重回帰分析","C":"クラスター分析","D":"因子分析"},"answer":"D","explanation":"潜在因子の探索＝因子分析。"},{"id":"E09Q31","exam":9,"number":31,"category":"構成管理","question":"保守フェーズにおいて、ベースラインの説明として適切なのはどれか。","options":{"A":"正式に合意され変更管理の対象となる基準状態","B":"最新ファイルなら何でもよい","C":"個人PCの一時保存","D":"バックアップだけを指す"},"answer":"A","explanation":"ベースライン変更は正式な変更管理下で行う。"},{"id":"E09Q32","exam":9,"number":32,"category":"構成管理","question":"保守フェーズにおいて、構成管理で不適切な行為はどれか。","options":{"A":"変更履歴を記録する","B":"担当者個人が無手続でベースライン変更を確定する","C":"リリース対象を管理する","D":"構成品目を識別する"},"answer":"B","explanation":"ベースライン変更は権限ある仕組みで統制する。"},{"id":"E09Q33","exam":9,"number":33,"category":"品質計画","question":"保守フェーズにおいて、品質計画について最も適切なものはどれか。","options":{"A":"合否基準を含めない","B":"品質評価計画を含めない","C":"一度作れば固定する","D":"要求やプロセス変更に応じて見直す"},"answer":"D","explanation":"品質計画は状況変化に応じて更新する。"},{"id":"E09Q34","exam":9,"number":34,"category":"改善","question":"保守フェーズにおいて、根本原因分析の目的として最も適切なものはどれか。","options":{"A":"欠陥件数を減らして記録する","B":"責任者を処罰する","C":"根本原因を特定し再発防止につなげる","D":"障害を一時回避するだけ"},"answer":"C","explanation":"原因の深掘りと再発防止が目的。"},{"id":"E09Q35","exam":9,"number":35,"category":"改善","question":"保守フェーズにおいて、pDCAの正しい順序はどれか。","options":{"A":"Plan→Check→Do→Act","B":"Plan→Do→Check→Act","C":"Do→Plan→Act→Check","D":"Plan→Act→Do→Check"},"answer":"B","explanation":"Plan, Do, Check, Act。"},{"id":"E09Q36","exam":9,"number":36,"category":"リスク","question":"保守フェーズにおいて、リスクベースドテストの考え方として適切なのはどれか。","options":{"A":"発生可能性や影響度を考慮して優先度を決める","B":"テストを行わずリスク評価だけする","C":"担当者の好みだけで決める","D":"全機能へ同量のテストを割り当てる"},"answer":"A","explanation":"高リスク領域へ重点的にテスト資源を配分する。"},{"id":"E09Q37","exam":9,"number":37,"category":"CI/CD","question":"保守フェーズにおいて、cIの説明として最も適切なものはどれか。","options":{"A":"統合を手作業中心にする","B":"自動化後は結果確認不要","C":"変更を頻繁に統合しビルドやテスト等を自動化する","D":"本番デプロイだけを指す"},"answer":"C","explanation":"CIは継続的統合。自動化しても結果確認は必要。"},{"id":"E09Q38","exam":9,"number":38,"category":"ITサービス","question":"保守フェーズにおいて、iTILが主に扱うものはどれか。","options":{"A":"UI設計だけ","B":"ITサービスマネジメント","C":"ソースコード生成","D":"統計解析だけ"},"answer":"B","explanation":"ITILはITサービスマネジメントのベストプラクティス。"},{"id":"E09Q39","exam":9,"number":39,"category":"セーフティ","question":"保守フェーズにおいて、ハザードの説明として適切なのはどれか。","options":{"A":"危害を引き起こす潜在的な原因","B":"実際に生じた損害そのもの","C":"品質目標","D":"構成品目"},"answer":"A","explanation":"ハザード＝危害につながる潜在的原因。"},{"id":"E09Q40","exam":9,"number":40,"category":"セーフティ","question":"保守フェーズにおいて、本質安全の考え方として最も近いものはどれか。","options":{"A":"ハザード発生後だけ警告する","B":"バックアップを取るだけ","C":"ログを残すだけ","D":"ハザードそのものを除去・低減する"},"answer":"D","explanation":"危険源そのものを抑える＝本質安全。 ---"},{"id":"E10Q01","exam":10,"number":1,"category":"セーフティ","question":"保守フェーズにおいて、機能安全の考え方として最も近いものはどれか。","options":{"A":"可用性だけを高める","B":"暗号化だけを行う","C":"安全関連機能によって危害へ至るリスクを低減する","D":"危険源を物理的に必ずゼロにする"},"answer":"C","explanation":"安全機能によってリスクを許容可能にする。"},{"id":"E10Q02","exam":10,"number":2,"category":"AI品質","question":"保守フェーズにおいて、aIシステムの品質評価で適切なものはどれか。","options":{"A":"テストは不要","B":"学習データやモデル特性も含めて評価する","C":"通常ソフトと完全に同じ観点だけで十分","D":"精度だけ見ればよい"},"answer":"B","explanation":"データ・モデル特有の品質も考慮する。"},{"id":"E10Q03","exam":10,"number":3,"category":"IoT品質","question":"保守フェーズにおいて、ioTシステムの品質で適切な考え方はどれか。","options":{"A":"デバイス・通信・クラウド等を含む全体を考慮する","B":"アプリ画面だけを見る","C":"ローカルPCだけを見る","D":"品質管理は不要"},"answer":"A","explanation":"複数要素からなるシステム全体で品質を捉える。"},{"id":"E10Q04","exam":10,"number":4,"category":"クラウド品質","question":"保守フェーズにおいて、クラウド利用時の品質で考慮すべきものはどれか。","options":{"A":"障害は起きないので品質活動不要","B":"テスト不要","C":"性能は常に一定","D":"可用性・セキュリティ・サービス依存性など"},"answer":"D","explanation":"クラウド固有の依存関係や運用品質も考慮する。"},{"id":"E10Q05","exam":10,"number":5,"category":"品質概念","question":"テスト計画を作成する際、verificationの説明として最も適切なものはどれか。","options":{"A":"市場シェアを確認する","B":"利用者のニーズに合う製品かを確認する","C":"成果物が規定要求どおり正しく作られているか確認する","D":"運用コストだけを確認する"},"answer":"C","explanation":"Verificationは「正しく作っているか」を確認する。Validationは「正しいものを作っているか」。"},{"id":"E10Q06","exam":10,"number":6,"category":"品質概念","question":"テスト計画を作成する際、validationの説明として最も適切なものはどれか。","options":{"A":"成果物が上位仕様に適合しているかだけを見る","B":"利用者の意図した用途・ニーズを満たすか確認する","C":"構成品目を識別する","D":"欠陥密度を測る"},"answer":"B","explanation":"Validationは意図した用途や利用者ニーズを満たすかを確認する。"},{"id":"E10Q07","exam":10,"number":7,"category":"品質モデル","question":"テスト計画を作成する際、通常運用時に信頼性要求を満たして安定して動作する性質はどれか。","options":{"A":"可用性","B":"障害許容性","C":"回復性","D":"成熟性"},"answer":"D","explanation":"平常時＝成熟性。"},{"id":"E10Q08","exam":10,"number":8,"category":"品質モデル","question":"テスト計画を作成する際、障害発生中でも必要な機能を継続できる性質はどれか。","options":{"A":"障害許容性","B":"回復性","C":"成熟性","D":"可用性"},"answer":"A","explanation":"障害中＝障害許容性。"},{"id":"E10Q09","exam":10,"number":9,"category":"品質モデル","question":"テスト計画を作成する際、障害後にデータや状態を復旧できる性質はどれか。","options":{"A":"回復性","B":"成熟性","C":"可用性","D":"障害許容性"},"answer":"A","explanation":"障害後＝回復性。"},{"id":"E10Q10","exam":10,"number":10,"category":"品質モデル","question":"テスト計画を作成する際、必要な時にシステムを利用できる性質はどれか。","options":{"A":"成熟性","B":"可用性","C":"障害許容性","D":"回復性"},"answer":"B","explanation":"利用可能である度合い＝可用性。"},{"id":"E10Q11","exam":10,"number":11,"category":"保守性","question":"テスト計画を作成する際、あるモジュールの変更が他モジュールへ波及しにくい性質はどれか。","options":{"A":"モジュール性","B":"修正性","C":"試験性","D":"解析性"},"answer":"A","explanation":"変更影響の局所化＝モジュール性。"},{"id":"E10Q12","exam":10,"number":12,"category":"保守性","question":"テスト計画を作成する際、障害原因や変更対象を調査しやすい性質はどれか。","options":{"A":"修正性","B":"試験性","C":"解析性","D":"再利用性"},"answer":"C","explanation":"原因・変更箇所を分析しやすい＝解析性。"},{"id":"E10Q13","exam":10,"number":13,"category":"保守性","question":"テスト計画を作成する際、変更後のソフトウェアを効率よくテストできる性質はどれか。","options":{"A":"試験性","B":"解析性","C":"再利用性","D":"修正性"},"answer":"A","explanation":"テストしやすさ＝試験性。"},{"id":"E10Q14","exam":10,"number":14,"category":"セキュリティ","question":"テスト計画を作成する際、許可されていない者による情報閲覧を防ぐ性質はどれか。","options":{"A":"機密性","B":"インテグリティ","C":"真正性","D":"責任追跡性"},"answer":"A","explanation":"見せない＝機密性。"},{"id":"E10Q15","exam":10,"number":15,"category":"セキュリティ","question":"テスト計画を作成する際、権限のない変更・改ざんを防ぐ性質はどれか。","options":{"A":"インテグリティ","B":"真正性","C":"否認防止性","D":"機密性"},"answer":"A","explanation":"変えさせない＝インテグリティ。"},{"id":"E10Q16","exam":10,"number":16,"category":"セキュリティ","question":"テスト計画を作成する際、操作を行った主体を後から追跡できる性質はどれか。","options":{"A":"否認防止性","B":"機密性","C":"真正性","D":"責任追跡性"},"answer":"D","explanation":"誰が行ったか追える＝責任追跡性。"},{"id":"E10Q17","exam":10,"number":17,"category":"セキュリティ","question":"テスト計画を作成する際、利用者が主張どおりの本人であることを確認する性質はどれか。","options":{"A":"インテグリティ","B":"真正性","C":"責任追跡性","D":"否認防止性"},"answer":"B","explanation":"本当に本人か＝真正性。"},{"id":"E10Q18","exam":10,"number":18,"category":"セキュリティ","question":"テスト計画を作成する際、電子的な操作を後から『自分はしていない』と否定できないようにする性質はどれか。","options":{"A":"真正性","B":"責任追跡性","C":"否認防止性","D":"機密性"},"answer":"C","explanation":"行為の否定を防ぐ＝否認防止性。"},{"id":"E10Q19","exam":10,"number":19,"category":"レビュー","question":"テスト計画を作成する際、インスペクションの特徴として最も適切なものはどれか。","options":{"A":"役割や手順を定め体系的に行う","B":"必ずプログラムを実行する","C":"テスト完了後だけ行う","D":"作成者だけで自由に確認する"},"answer":"A","explanation":"インスペクションは比較的形式的なレビュー。"},{"id":"E10Q20","exam":10,"number":20,"category":"レビュー","question":"テスト計画を作成する際、ウォークスルーの特徴として最も適切なものはどれか。","options":{"A":"動的テストの一種である","B":"構成管理の一種である","C":"作成者が説明を主導することが多い","D":"必ず監査部門が主導する"},"answer":"C","explanation":"ウォークスルーは作成者主導で説明・確認する形が代表的。"},{"id":"E10Q21","exam":10,"number":21,"category":"テスト","question":"テスト計画を作成する際、同値分割法の説明として最も適切なものはどれか。","options":{"A":"無作為値だけを使う","B":"同様の振る舞いが期待される入力集合に分割する","C":"境界値だけを試す","D":"内部分岐をすべて実行する"},"answer":"B","explanation":"同値クラスごとに代表値を選ぶ。"},{"id":"E10Q22","exam":10,"number":22,"category":"テスト","question":"入力範囲が1以上100以下のとき、境界値分析で特に有効な組合せはどれか。","options":{"A":"25,50,75","B":"1,100","C":"0,1,100,101","D":"10,20,30,40"},"answer":"C","explanation":"境界の直前・境界・直後を重視する。"},{"id":"E10Q23","exam":10,"number":23,"category":"テスト","question":"テスト計画を作成する際、複数条件の組合せと結果の関係を整理してテストする技法はどれか。","options":{"A":"デシジョンテーブルテスト","B":"命令網羅","C":"探索的テスト","D":"状態遷移テスト"},"answer":"A","explanation":"条件組合せ＝デシジョンテーブル。"},{"id":"E10Q24","exam":10,"number":24,"category":"テスト","question":"テスト計画を作成する際、状態によって同じイベントへの応答が変化するシステムに適した技法はどれか。","options":{"A":"分岐網羅","B":"静的解析","C":"状態遷移テスト","D":"同値分割"},"answer":"C","explanation":"状態と遷移を持つ対象には状態遷移テスト。"},{"id":"E10Q25","exam":10,"number":25,"category":"テスト","question":"テスト計画を作成する際、変更による既存機能への悪影響を確認するテストはどれか。","options":{"A":"ユーザビリティテスト","B":"受入テスト","C":"回帰テスト","D":"負荷テスト"},"answer":"C","explanation":"変更後の副作用確認＝回帰テスト。"},{"id":"E10Q26","exam":10,"number":26,"category":"テスト","question":"テスト計画を作成する際、内部の制御構造を基に網羅率を測るテストはどれか。","options":{"A":"ブラックボックステスト","B":"ホワイトボックステスト","C":"受入テスト","D":"ユーザビリティテスト"},"answer":"B","explanation":"命令・分岐など内部構造に着目＝ホワイトボックス。"},{"id":"E10Q27","exam":10,"number":27,"category":"テスト","question":"テスト計画を作成する際、テストで欠陥が見つからなかった場合の判断として適切なのはどれか。","options":{"A":"品質100%である","B":"実施したテストでは発見されなかっただけである","C":"テストは不要だった","D":"欠陥が存在しないことが証明された"},"answer":"B","explanation":"テストは欠陥の不在を完全には証明できない。"},{"id":"E10Q28","exam":10,"number":28,"category":"品質管理","question":"テスト計画を作成する際、パレート図の主な用途はどれか。","options":{"A":"二変数の相関を見る","B":"原因候補を枝状に整理する","C":"時系列変化を監視する","D":"重要な問題を優先順位付けする"},"answer":"D","explanation":"大きい項目から並べ重点問題を把握する。"},{"id":"E10Q29","exam":10,"number":29,"category":"品質管理","question":"テスト計画を作成する際、特性要因図の主な用途はどれか。","options":{"A":"テストケースを生成する","B":"原因候補を体系的に整理する","C":"頻度順に並べる","D":"時系列の管理限界を見る"},"answer":"B","explanation":"結果と原因候補を魚の骨状に整理する。"},{"id":"E10Q30","exam":10,"number":30,"category":"品質管理","question":"テスト計画を作成する際、散布図の主な用途はどれか。","options":{"A":"二つの変数の関係を観察する","B":"原因候補を階層化する","C":"頻度順に並べる","D":"構成品目を管理する"},"answer":"A","explanation":"二変数間の関係を見る。"},{"id":"E10Q31","exam":10,"number":31,"category":"品質管理","question":"テスト計画を作成する際、管理図の主な用途はどれか。","options":{"A":"機能要求を整理する","B":"コードを自動生成する","C":"レビュー役割を定義する","D":"プロセスの変動が統計的に安定しているか監視する"},"answer":"D","explanation":"管理限界などを用いて工程の安定性を見る。"},{"id":"E10Q32","exam":10,"number":32,"category":"品質コスト","question":"テスト計画を作成する際、品質教育や標準化活動に要する費用はどれか。","options":{"A":"内部失敗コスト","B":"外部失敗コスト","C":"予防コスト","D":"評価コスト"},"answer":"C","explanation":"不良を未然に防ぐ活動＝予防コスト。"},{"id":"E10Q33","exam":10,"number":33,"category":"品質コスト","question":"テスト計画を作成する際、出荷前の検査・テストに要する費用はどれか。","options":{"A":"外部失敗コスト","B":"予防コスト","C":"評価コスト","D":"内部失敗コスト"},"answer":"C","explanation":"適合性を評価する活動＝評価コスト。"},{"id":"E10Q34","exam":10,"number":34,"category":"品質コスト","question":"テスト計画を作成する際、出荷前に発見された欠陥の修正費用はどれか。","options":{"A":"予防コスト","B":"評価コスト","C":"内部失敗コスト","D":"外部失敗コスト"},"answer":"C","explanation":"顧客へ渡る前の失敗＝内部失敗コスト。"},{"id":"E10Q35","exam":10,"number":35,"category":"品質コスト","question":"テスト計画を作成する際、市場で発生した障害・クレームへの対応費用はどれか。","options":{"A":"評価コスト","B":"内部失敗コスト","C":"外部失敗コスト","D":"予防コスト"},"answer":"C","explanation":"顧客へ渡った後の失敗＝外部失敗コスト。"},{"id":"E10Q36","exam":10,"number":36,"category":"メトリクス","question":"テスト計画を作成する際、gQMの正しい展開順序はどれか。","options":{"A":"Graph→Question→Measure","B":"Goal→Query→Model","C":"Goal→Quality→Metric","D":"Goal→Question→Metric"},"answer":"D","explanation":"GQM = Goal, Question, Metric。"},{"id":"E10Q37","exam":10,"number":37,"category":"メトリクス","question":"テスト計画を作成する際、欠陥密度の例として最も適切なものはどれか。","options":{"A":"平均給与","B":"KLOC当たりの欠陥数","C":"1日当たり勤務時間","D":"CPU使用率"},"answer":"B","explanation":"規模当たり欠陥数が代表例。"},{"id":"E10Q38","exam":10,"number":38,"category":"信頼性指標","question":"テスト計画を作成する際、mTBFが表すものはどれか。","options":{"A":"平均修復時間","B":"平均故障間隔","C":"平均応答時間","D":"平均テスト時間"},"answer":"B","explanation":"MTBF = Mean Time Between Failures。"},{"id":"E10Q39","exam":10,"number":39,"category":"信頼性指標","question":"テスト計画を作成する際、mTTRが一般に表すものはどれか。","options":{"A":"平均故障間隔","B":"平均レビュー時間","C":"平均要求数","D":"平均修復時間"},"answer":"D","explanation":"MTTR = Mean Time To Repair/Recovery。"},{"id":"E10Q40","exam":10,"number":40,"category":"統計","question":"1つの目的変数を複数の説明変数から説明・予測する代表的手法はどれか。","options":{"A":"因子分析","B":"パレート分析","C":"重回帰分析","D":"クラスター分析"},"answer":"C","explanation":"複数説明変数→1目的変数＝重回帰分析。"}];
